// 物理 题库（wl）：赤峰中考诊断。原创题，仿内蒙古中考风格。
ZK.banks.push({
  file: "wl",
  passages: [],
  items: [
    {"id":"wl.shengguang-L1-01","module":"wl.shengguang","level":1,"kp":"声音的产生与传播","prompt":"关于声现象，下列说法正确的是","choices":["声音在真空中传播得最快","只要物体在振动，我们就一定能听到声音","声音在空气中的传播速度约为3×10^{8} m/s","一切正在发声的物体都在振动"],"answer":3,"explain":"声音由物体振动产生，发声体一定在振动。声音的传播需要介质，真空不能传声；振动频率不在人耳听觉范围内或没有介质时听不到；空气中声速约340 m/s，3×10^{8} m/s是光速。"},
    {"id":"wl.shengguang-L1-02","module":"wl.shengguang","level":1,"kp":"声音的特性","prompt":"“闻其声而知其人”，主要是根据声音的哪个特性来判断的？","choices":["音调","音色","响度","传播速度"],"answer":1,"explain":"不同人的发声体结构不同，发出声音的音色不同，因此能凭声音辨别人。音调与频率有关，响度与振幅有关，声速与介质有关，都不能用来区分说话的人。"},
    {"id":"wl.shengguang-L1-03","module":"wl.shengguang","level":1,"kp":"光现象辨析","prompt":"下列现象中，由光的直线传播形成的是","choices":["树荫下地面上的圆形光斑","平静湖面上桥的倒影","雨后天空出现的彩虹","插入水中的筷子在水面处“折断”"],"answer":0,"explain":"树荫下的圆形光斑是太阳通过树叶缝隙小孔成的像，属于光的直线传播。倒影是平面镜成像（光的反射）；彩虹是光的色散（折射）；筷子“折断”是光的折射。"},
    {"id":"wl.shengguang-L1-04","module":"wl.shengguang","level":1,"kp":"平面镜成像特点","prompt":"小明站在竖直放置的平面镜前2 m处。他的像到他本人的距离，以及他走近镜子时像的大小变化分别是","choices":["2 m，像的大小不变","4 m，像变大","4 m，像的大小不变","2 m，像变大"],"answer":2,"explain":"像到镜面的距离等于物到镜面的距离，也是2 m，所以像与人相距2+2=4 m。平面镜成等大的虚像，像的大小只与物体大小有关，走近时“看起来变大”只是视角变大。"},
    {"id":"wl.shengguang-L1-05","module":"wl.shengguang","level":1,"kp":"噪声的控制","prompt":"城区某些路段设置了“禁止鸣笛”标志，这种控制噪声的方法属于","choices":["在传播过程中减弱噪声","在人耳处减弱噪声","通过降低音调来减弱噪声","在声源处减弱噪声"],"answer":3,"explain":"禁止鸣笛是不让声源发声，属于在声源处减弱。隔音墙、植树属于传播过程中减弱；戴耳塞属于在人耳处减弱。减弱噪声主要是减小响度，与降低音调无关。"},
    {"id":"wl.shengguang-L2-01","module":"wl.shengguang","level":2,"kp":"眼睛与眼镜","prompt":"关于近视眼的成因及矫正，下列说法正确的是","choices":["像成在视网膜前方，用凹透镜矫正","像成在视网膜后方，用凸透镜矫正","像成在视网膜前方，用凸透镜矫正","像成在视网膜后方，用凹透镜矫正"],"answer":0,"explain":"近视眼晶状体太厚、折光能力太强，远处物体的像成在视网膜前方；需要配戴对光有发散作用的凹透镜，使像后移到视网膜上。像成在视网膜后方是远视眼，用凸透镜矫正。"},
    {"id":"wl.shengguang-L2-02","module":"wl.shengguang","level":2,"kp":"凸透镜成像规律","prompt":"凸透镜的焦距为10 cm，将蜡烛放在距透镜15 cm处，移动光屏可得到清晰的像。这个像的性质及其应用是","choices":["倒立、缩小的实像，应用于照相机","正立、放大的虚像，应用于放大镜","倒立、放大的实像，应用于投影仪","倒立、等大的实像，可用于测焦距"],"answer":2,"explain":"f=10 cm，u=15 cm，满足f＜u＜2f，成倒立、放大的实像，投影仪就是这个原理。u＞2f才成缩小实像（照相机）；u＜f成正立放大虚像（放大镜），且虚像不能用光屏承接。"},
    {"id":"wl.shengguang-L2-03","module":"wl.shengguang","level":2,"kp":"光的反射定律","prompt":"一束光与平面镜的夹角为30°射到镜面上，反射角为___；若入射角增大10°，则反射光线与入射光线的夹角变为___。","choices":["30°；80°","60°；140°","60°；130°","30°；120°"],"answer":1,"explain":"入射角是入射光线与法线的夹角：90°−30°=60°，反射角等于入射角，也是60°。入射角增大10°变为70°，反射角也为70°，两光线夹角为70°+70°=140°。常见错误是把30°直接当作入射角。"},
    {"id":"wl.shengguang-L2-04","module":"wl.shengguang","level":2,"kp":"回声测距","prompt":"小明对着远处的山崖大喊一声，2 s后听到回声。已知声音在空气中的传播速度为340 m/s，小明到山崖的距离约为","choices":["680 m","170 m","1020 m","340 m"],"answer":3,"explain":"声音传到山崖再返回共用2 s，单程用时1 s，所以距离s=vt=340 m/s×1 s=340 m。若直接用2 s计算得680 m，是把往返路程当成了单程距离。"},
    {"id":"wl.shengguang-L2-05","module":"wl.shengguang","level":2,"kp":"光的折射","prompt":"站在清澈的水池边看池底，觉得池水比实际的浅。产生这种现象的原因是","choices":["光从空气斜射入水时发生折射，折射角小于入射角","光从水斜射入空气时发生折射，折射角大于入射角","光从水斜射入空气时发生折射，折射角小于入射角","光在水面发生反射，形成了池底的虚像"],"answer":1,"explain":"池底反射的光从水斜射入空气，在水面发生折射，折射角大于入射角，人逆着折射光线看去，看到的是池底偏高的虚像，所以觉得变浅。光的传播方向是从池底到人眼，不是从空气射入水。"},
    {"id":"wl.shengguang-L3-01","module":"wl.shengguang","level":3,"kp":"凸透镜成像规律","prompt":"做凸透镜成像实验时，蜡烛距透镜30 cm，光屏上恰好得到倒立、等大的清晰像。保持透镜不动，将蜡烛移到距透镜20 cm处，要再次得到清晰的像，应","choices":["将光屏远离透镜，得到倒立、放大的实像","将光屏靠近透镜，得到倒立、缩小的实像","无论怎样移动光屏都得不到像，此时成正立、放大的虚像","将光屏靠近透镜，得到倒立、放大的实像"],"answer":0,"explain":"成等大像时u=2f=30 cm，所以f=15 cm。蜡烛移到20 cm处，f＜u＜2f，成倒立放大的实像，像距v＞2f=30 cm，因此光屏要远离透镜。规律：成实像时“物近像远像变大”。"},
    {"id":"wl.shengguang-L3-02","module":"wl.shengguang","level":3,"kp":"凸透镜焦距范围判断","prompt":"蜡烛距凸透镜20 cm时，在透镜另一侧12 cm处的光屏上得到一个倒立、缩小的清晰像。该凸透镜的焦距f满足","choices":["10 cm＜f＜12 cm","f＜6 cm","6 cm＜f＜10 cm","12 cm＜f＜20 cm"],"answer":2,"explain":"成倒立缩小实像时u＞2f、f＜v＜2f。由20 cm＞2f得f＜10 cm；由f＜12 cm＜2f得6 cm＜f＜12 cm。两者同时满足：6 cm＜f＜10 cm。只用其中一个不等式就会选错。"},
    {"id":"wl.shengguang-L3-03","module":"wl.shengguang","level":3,"kp":"平面镜成像实验","prompt":"关于“探究平面镜成像特点”的实验，下列说法正确的是","choices":["用玻璃板代替平面镜，主要是为了使像更清晰","将蜡烛远离玻璃板，它的像会变小","实验应在较明亮的环境中进行，像会更清楚","在像的位置放一光屏，光屏上承接不到像，说明平面镜成的是虚像"],"answer":3,"explain":"虚像不能用光屏承接，这正是判断虚像的方法。用玻璃板是因为它透光，便于确定像的位置，不是使像更清晰；像与物始终等大；环境较暗时，点燃的蜡烛与环境对比更强，像更清楚。"},
    {"id":"wl.shengguang-L3-04","module":"wl.shengguang","level":3,"kp":"声音的特性","prompt":"8个相同的玻璃瓶中装有不同高度的水。用筷子敲击瓶子和用嘴对着瓶口吹气都能发出声音，下列判断正确的是","choices":["敲击时水越多音调越低；吹气时水越多音调越高","敲击时水越多音调越高；吹气时水越多音调越低","敲击和吹气时，都是水越多音调越高","敲击和吹气时，都是水越多音调越低"],"answer":0,"explain":"敲击时主要是瓶和水振动，水越多越难振动、频率越低，音调越低；吹气时是瓶内空气柱振动，水越多空气柱越短、频率越高，音调越高。关键是先找准“谁在振动”。"},
    {"id":"wl.shengguang-L3-05","module":"wl.shengguang","level":3,"kp":"凸透镜成像动态规律","prompt":"用照相机给同学拍完全身照后，同学站在原处不动，想再拍一张半身特写（像要变大）。下列做法正确的是","choices":["照相机靠近同学，同时镜头向后缩","照相机靠近同学，同时镜头向前伸","照相机远离同学，同时镜头向前伸","照相机远离同学，同时镜头向后缩"],"answer":1,"explain":"要使实像变大，需减小物距、增大像距，即“物近像远像变大”。所以照相机要靠近同学（物距减小），镜头前伸使镜头到底片的距离增大（像距增大）。"},
    {"id":"wl.shengguang-L4-01","module":"wl.shengguang","level":4,"kp":"光路可逆与成像","prompt":"蜡烛与光屏相距45 cm且位置固定，在两者之间移动凸透镜。当透镜距蜡烛15 cm时，光屏上出现清晰的像。下列说法正确的是","choices":["透镜距蜡烛15 cm时，光屏上成倒立、缩小的实像","该透镜的焦距可能是16 cm","将透镜移到距蜡烛30 cm处，光屏上会再次出现倒立、缩小的清晰像","将透镜移到距蜡烛30 cm处，光屏上会出现倒立、放大的清晰像"],"answer":2,"explain":"第一次u=15 cm，v=30 cm，v＞u成倒立放大实像，由f＜15 cm＜2f且30 cm＞2f得7.5 cm＜f＜15 cm，不可能是16 cm。由光路可逆，把物距、像距对调（u=30 cm，v=15 cm）还能成清晰像，此时u＞v，是倒立缩小的实像。"},
    {"id":"wl.shengguang-L4-02","module":"wl.shengguang","level":4,"kp":"光的反射定律","prompt":"一束光以40°的入射角射到平面镜上。保持入射光线不动，将平面镜绕入射点转动10°，使入射角增大。则反射光线转过的角度和此时反射光线与入射光线的夹角分别为","choices":["20°；100°","10°；100°","20°；90°","10°；90°"],"answer":0,"explain":"镜面转10°，法线也转10°，入射角变为50°，反射角也为50°，两光线夹角为100°（原来80°）。入射光线不动，反射光线与入射光线的夹角增大了20°，所以反射光线转过20°，即“镜转θ，反射光转2θ”。"},
    {"id":"wl.shengguang-L4-03","module":"wl.shengguang","level":4,"kp":"回声测距","prompt":"一辆汽车以20 m/s的速度匀速驶向山崖，司机鸣笛后经过2 s听到回声（声速取340 m/s）。司机鸣笛时汽车到山崖的距离为","choices":["340 m","360 m","320 m","380 m"],"answer":1,"explain":"2 s内声音传播340×2=680 m，汽车前进20×2=40 m。声音走的路程与车走的路程之和等于鸣笛处到山崖距离的2倍：2s=680+40，s=360 m。听到回声时车离山崖360−40=320 m，注意问的是哪一时刻。"},
    {"id":"wl.shengguang-L4-04","module":"wl.shengguang","level":4,"kp":"眼睛与眼镜","prompt":"在凸透镜成像实验中，光屏上已有清晰的像。将一副近视眼镜放在蜡烛和凸透镜之间，像变模糊了。若保持凸透镜和光屏不动，要使光屏上重新得到清晰的像，蜡烛应","choices":["靠近凸透镜","保持不动，像会自己变清晰","远离凸透镜","靠近凸透镜并移到一倍焦距以内"],"answer":2,"explain":"近视眼镜是凹透镜，对光有发散作用，使成像位置后移到光屏后方。光屏不动时，要让像前移，需增大物距（物远像近），所以蜡烛应远离凸透镜。移到一倍焦距以内成虚像，光屏承接不到。"},
    {"id":"wl.shengguang-L4-05","module":"wl.shengguang","level":4,"kp":"光的折射","prompt":"渔民在岸上看到水中的鱼。若用鱼叉叉鱼、用激光笔照射鱼，为了命中，应分别瞄准","choices":["鱼叉对准看到的“鱼”；激光对准看到的“鱼”的下方","鱼叉和激光都对准看到的“鱼”","鱼叉和激光都对准看到的“鱼”的下方","鱼叉对准看到的“鱼”的下方；激光对准看到的“鱼”"],"answer":3,"explain":"看到的“鱼”是光折射形成的偏高的虚像，真实的鱼在它下方，鱼叉沿直线前进，要对准像的下方。激光射入水中也会发生折射，由光路可逆，沿着看到“鱼”的方向照射，折射后正好射到鱼身上。"},
    {"id":"wl.re-L1-01","module":"wl.re","level":1,"kp":"物态变化辨析","prompt":"寒冬的早晨，窗玻璃内侧出现美丽的“冰花”。“冰花”形成的物态变化是","choices":["凝固","凝华","液化","升华"],"answer":1,"explain":"“冰花”是室内温度较高的水蒸气遇到冰冷的玻璃，直接由气态变成固态的小冰晶，属于凝华。凝固是液态变固态，液化是气态变液态，升华是固态直接变气态。"},
    {"id":"wl.re-L1-02","module":"wl.re","level":1,"kp":"熔化和凝固","prompt":"冰在熔化过程中","choices":["吸收热量，温度不断升高","放出热量，温度保持不变","吸收热量，温度保持不变","既不吸热也不放热，温度不变"],"answer":2,"explain":"冰是晶体，熔化时持续吸热，但温度保持在熔点0 ℃不变，直到全部熔化。非晶体熔化时吸热温度才不断升高；放热温度不变描述的是晶体凝固。"},
    {"id":"wl.re-L1-03","module":"wl.re","level":1,"kp":"改变内能的方式","prompt":"下列实例中，通过做功改变物体内能的是","choices":["冬天两手相互摩擦，手变热","用热水袋暖手","在阳光下晒被子","把饮料放进冰箱冷藏"],"answer":0,"explain":"搓手时克服摩擦做功，机械能转化为内能，属于做功改变内能。热水袋暖手、晒被子、冰箱冷藏都是能量从高温物体转移到低温物体，属于热传递。"},
    {"id":"wl.re-L1-04","module":"wl.re","level":1,"kp":"比热容的应用","prompt":"汽车发动机常用水作为冷却剂，主要是因为水的","choices":["密度较大","沸点较高","热值较大","比热容较大"],"answer":3,"explain":"水的比热容大，质量相同、升高相同温度时能吸收更多热量，冷却效果好。热值是燃料的特性，与冷却无关；密度、沸点不是选用水作冷却剂的主要原因。"},
    {"id":"wl.re-L1-05","module":"wl.re","level":1,"kp":"热机的冲程","prompt":"四冲程汽油机工作时，将内能转化为机械能的是","choices":["做功冲程","压缩冲程","吸气冲程","排气冲程"],"answer":0,"explain":"做功冲程中，高温高压燃气推动活塞做功，内能转化为机械能。压缩冲程正好相反，是机械能转化为内能；吸气、排气冲程没有这两种能量转化。"},
    {"id":"wl.re-L2-01","module":"wl.re","level":2,"kp":"热量计算","prompt":"质量为2 kg的水，温度从20 ℃升高到70 ℃，吸收的热量是多少？[c_{水}=4.2×10^{3} J/(kg·℃)]","choices":["2.1×10^{5} J","5.88×10^{5} J","8.4×10^{5} J","4.2×10^{5} J"],"answer":3,"explain":"Q吸=cmΔt=4.2×10^{3} J/(kg·℃)×2 kg×(70−20)℃=4.2×10^{5} J。若误把末温70 ℃当作温度变化量，会得到5.88×10^{5} J；漏乘质量2 kg会得到2.1×10^{5} J。"},
    {"id":"wl.re-L2-02","module":"wl.re","level":2,"kp":"燃料的热值","prompt":"焦炭的热值为3.0×10^{7} J/kg，完全燃烧0.5 kg焦炭放出的热量是","choices":["3.0×10^{7} J","1.5×10^{7} J","6.0×10^{7} J","1.5×10^{6} J"],"answer":1,"explain":"Q放=mq=0.5 kg×3.0×10^{7} J/kg=1.5×10^{7} J。热值表示1 kg燃料完全燃烧放出的热量，0.5 kg放出的热量只有一半；用除法会得到6.0×10^{7} J。"},
    {"id":"wl.re-L2-03","module":"wl.re","level":2,"kp":"温度热量内能关系","prompt":"关于温度、热量和内能，下列说法正确的是","choices":["物体温度越高，含有的热量越多","物体吸收热量，温度一定升高","同一物体温度升高，内能一定增加","0 ℃的冰没有内能"],"answer":2,"explain":"同一物体温度升高，分子运动加剧，内能一定增加。热量是过程量，只能说“吸收”或“放出”，不能说“含有”；晶体熔化、液体沸腾时吸热温度不变；一切物体都有内能，0 ℃的冰也有。"},
    {"id":"wl.re-L2-04","module":"wl.re","level":2,"kp":"物态变化辨析","prompt":"夏天从冰箱里拿出一瓶饮料，过一会儿瓶的外壁“出汗”了。这是因为","choices":["瓶内的饮料渗透到了瓶外","空气中的水蒸气遇到冷的瓶壁液化成小水珠","瓶壁上的冰熔化成了水","空气中的水蒸气在瓶壁上凝华成小水珠"],"answer":1,"explain":"瓶壁温度低，周围空气中的水蒸气遇冷放热，液化成小水珠附着在瓶外壁。饮料不会渗出瓶壁；凝华的产物是固态小冰晶而不是水珠。"},
    {"id":"wl.re-L2-05","module":"wl.re","level":2,"kp":"沸腾实验","prompt":"在“探究水沸腾时温度变化的特点”实验中，下列说法正确的是","choices":["水沸腾后撤去酒精灯，水仍能长时间持续沸腾","测得水的沸点为98 ℃，说明当地气压高于1个标准大气压","水沸腾时持续吸热，温度保持不变","沸腾时，水中气泡在上升过程中逐渐变小"],"answer":2,"explain":"沸腾的特点是持续吸热、温度不变。撤去酒精灯水不能继续吸热，很快停止沸腾；沸点低于100 ℃说明气压低于1个标准大气压；沸腾时气泡上升逐渐变大，沸腾前气泡上升变小。"},
    {"id":"wl.re-L2-06","module":"wl.re","level":2,"kp":"能量转化与守恒","prompt":"关于能量的转化和守恒，下列说法正确的是","choices":["能量是守恒的，所以不会发生能源危机","改进技术后，热机的效率可以达到100%","能量在转化和转移过程中，总量会逐渐减少","“永动机”不可能制成，因为它违背了能量守恒定律"],"answer":3,"explain":"能量既不会凭空产生也不会凭空消失，永动机违背能量守恒定律，不可能制成。能量总量不变，但能量转化具有方向性，可利用的能源会减少，所以存在能源危机；热机总有能量损失，效率不可能达到100%。"},
    {"id":"wl.re-L3-01","module":"wl.re","level":3,"kp":"比热容图像与计算","stem":"用两个相同的电加热器分别给质量相同的水和某种液体加热，记录数据如下：\n加热时间/min：0　　2　　4\n水的温度/℃：20　　30　　40\n液体的温度/℃：20　　40　　60","prompt":"已知c_{水}=4.2×10^{3} J/(kg·℃)，不计热损失，这种液体的比热容为","choices":["2.1×10^{3} J/(kg·℃)","8.4×10^{3} J/(kg·℃)","4.2×10^{3} J/(kg·℃)","1.05×10^{3} J/(kg·℃)"],"answer":0,"explain":"加热器相同，相同时间内两者吸热相同。加热4 min，水升温20 ℃，液体升温40 ℃。由Q=cmΔt，m、Q相同时c与Δt成反比，c液=c水×20/40=2.1×10^{3} J/(kg·℃)。升温快的物质比热容小，若认为升温快比热容大就会选8.4×10^{3}。"},
    {"id":"wl.re-L3-02","module":"wl.re","level":3,"kp":"热效率计算","prompt":"用燃气灶将5 kg的水从20 ℃加热到100 ℃，消耗天然气0.1 m³。已知天然气热值q=4.2×10^{7} J/m³，c_{水}=4.2×10^{3} J/(kg·℃)。燃气灶烧水的效率为","choices":["25%","40%","60%","50%"],"answer":1,"explain":"Q吸=cmΔt=4.2×10^{3}×5×80 J=1.68×10^{6} J；Q放=Vq=0.1×4.2×10^{7} J=4.2×10^{6} J；η=Q吸/Q放=1.68×10^{6}/4.2×10^{6}=40%。注意Δt=80 ℃，不是100 ℃。"},
    {"id":"wl.re-L3-03","module":"wl.re","level":3,"kp":"热机的冲程","prompt":"某单缸四冲程汽油机飞轮的转速为1800 r/min，则该汽油机每秒对外做功","choices":["30次","60次","15次","7.5次"],"answer":2,"explain":"1800 r/min=30 r/s。一个工作循环飞轮转2圈、经历4个冲程、对外做功1次，所以每秒完成15个循环，做功15次（共60个冲程）。常见错误是把转数30直接当作做功次数。"},
    {"id":"wl.re-L3-04","module":"wl.re","level":3,"kp":"物态变化辨析","prompt":"人工降雨时，把干冰（固态二氧化碳）撒在高空云层中，就可能降雨。在这一过程中，依次发生的主要物态变化是","choices":["干冰升华吸热，水蒸气遇冷凝华成小冰晶，小冰晶下落时熔化成雨","干冰熔化吸热，水蒸气液化成小水滴落下","干冰升华放热，水蒸气凝固成小冰晶，小冰晶液化成雨","干冰汽化吸热，水蒸气凝华成小冰晶，小冰晶升华成雨"],"answer":0,"explain":"干冰直接由固态变为气态是升华，升华吸热使周围温度骤降；高空水蒸气遇冷直接凝华成小冰晶；小冰晶下落遇暖空气熔化成水，形成雨。凝固是液变固，液化是气变液，均不符合。"},
    {"id":"wl.re-L3-05","module":"wl.re","level":3,"kp":"热平衡计算","prompt":"将0.2 kg、80 ℃的热水与0.3 kg、20 ℃的冷水混合，不计热量损失，混合后水的温度是","choices":["50 ℃","56 ℃","40 ℃","44 ℃"],"answer":3,"explain":"热水放热等于冷水吸热：c×0.2×(80−t)=c×0.3×(t−20)，16−0.2t=0.3t−6，t=44 ℃。直接取平均值得50 ℃是忽略了两部分水质量不同；冷水多，末温更接近20 ℃。"},
    {"id":"wl.re-L4-01","module":"wl.re","level":4,"kp":"热机效率计算","prompt":"一辆汽车在平直公路上匀速行驶9.2 km，受到的阻力为1000 N，消耗汽油0.8 kg（汽油热值q=4.6×10^{7} J/kg）。该汽车发动机的效率为","choices":["20%","25%","30%","40%"],"answer":1,"explain":"匀速行驶时牵引力F=f=1000 N，W=Fs=1000 N×9200 m=9.2×10^{6} J；Q放=mq=0.8×4.6×10^{7} J=3.68×10^{7} J；η=W/Q放=9.2×10^{6}/3.68×10^{7}=25%。注意路程要换算成9200 m。"},
    {"id":"wl.re-L4-02","module":"wl.re","level":4,"kp":"比热容图像与计算","prompt":"用功率恒定的加热器给0.5 kg、−10 ℃的冰加热（不计热损失），经过2 min冰的温度升到0 ℃。冰全部熔化成水后，水的温度再升高10 ℃需要加热多长时间？[c_{冰}=2.1×10^{3} J/(kg·℃)，c_{水}=4.2×10^{3} J/(kg·℃)]","choices":["2 min","1 min","8 min","4 min"],"answer":3,"explain":"冰升温10 ℃吸热Q=2.1×10^{3}×0.5×10 J=1.05×10^{4} J，用时2 min。水升温10 ℃吸热4.2×10^{3}×0.5×10 J=2.1×10^{4} J，是前者的2倍，加热器每分钟供热相同，所以需要4 min。冰熔化成水质量不变，比热容变大，同样升温需要更多时间。"},
    {"id":"wl.re-L4-03","module":"wl.re","level":4,"kp":"热平衡计算","prompt":"把质量为0.1 kg的金属块放在沸水中加热到100 ℃，迅速放入0.2 kg、20 ℃的水中，最终水和金属块的温度都为30 ℃。不计热量损失，该金属的比热容约为","choices":["1.05×10^{3} J/(kg·℃)","0.6×10^{3} J/(kg·℃)","1.2×10^{3} J/(kg·℃)","2.4×10^{3} J/(kg·℃)"],"answer":2,"explain":"水吸热Q=4.2×10^{3}×0.2×(30−20) J=8400 J。金属放热等于水吸热，金属降温Δt=100−30=70 ℃，c=Q/(mΔt)=8400/(0.1×70)=1.2×10^{3} J/(kg·℃)。若把金属的Δt误算成80 ℃，得1.05×10^{3}。"},
    {"id":"wl.re-L4-04","module":"wl.re","level":4,"kp":"物态变化吸放热","stem":"① 被100 ℃的水蒸气烫伤比被100 ℃的开水烫伤更严重，是因为水蒸气液化时放热\n② 冬天室外冰冻的衣服也能变干，是升华现象，需要吸热\n③ 白炽灯用久了灯丝变细、灯泡内壁变黑，是钨先升华后凝华\n④ 夏天吃冰棒感觉凉爽，是因为冰棒升华吸热","prompt":"以上说法中正确的是","choices":["只有①②③","只有①②④","只有②③④","①②③④"],"answer":0,"explain":"①水蒸气先液化放出大量热，再与开水一样放热，烫伤更重，正确；②冰直接变成水蒸气是升华，吸热，正确；③钨丝受热升华变细，钨蒸气遇冷凝华在内壁变黑，正确；④冰棒在嘴里是熔化吸热，不是升华，错误。","fixed":true},
    {"id":"wl.re-L4-05","module":"wl.re","level":4,"kp":"热机的冲程","prompt":"某单缸四冲程汽油机飞轮转速为2400 r/min，每个做功冲程中燃气对活塞做功500 J。该汽油机的功率为","choices":["10 kW","20 kW","40 kW","5 kW"],"answer":0,"explain":"2400 r/min=40 r/s，飞轮转2圈做功1次，每秒做功20次，每秒做功W=20×500 J=1×10^{4} J，P=10 kW。若以为每转做功一次得20 kW，以为每个冲程做功一次得更大的值。"},
    {"id":"wl.li-L1-01","module":"wl.li","level":1,"kp":"物理量估测","prompt":"下列对一名初三学生相关物理量的估测，最接近实际的是","choices":["质量约为50 kg","课桌高度约为80 dm","正常步行速度约为5 m/s","一个鸡蛋的重力约为5 N"],"answer":0,"explain":"初三学生质量约50 kg，符合实际。课桌高约80 cm=8 dm；正常步行约1.1 m/s，5 m/s接近跑步速度；一个鸡蛋约50 g，重约0.5 N。"},
    {"id":"wl.li-L1-02","module":"wl.li","level":1,"kp":"参照物与相对运动","prompt":"坐在行驶列车上的乘客认为自己是静止的，他所选的参照物是","choices":["路边的树","乘坐的车厢","铁轨","迎面驶来的列车"],"answer":1,"explain":"乘客相对于自己乘坐的车厢位置没有变化，所以以车厢为参照物他是静止的。相对于路边的树、铁轨和迎面驶来的列车，乘客的位置都在变化，是运动的。"},
    {"id":"wl.li-L1-03","module":"wl.li","level":1,"kp":"惯性","prompt":"关于惯性，下列说法正确的是","choices":["物体运动的速度越大，惯性越大","静止的物体没有惯性","系安全带可以减小乘客的惯性","汽车急刹车时乘客向前倾，是因为乘客具有惯性"],"answer":3,"explain":"刹车时乘客下半身随车减速，上半身由于惯性保持原来的运动状态，所以向前倾。惯性只与质量有关，与速度、是否运动无关；安全带是减小惯性带来的伤害，不能减小惯性。"},
    {"id":"wl.li-L1-04","module":"wl.li","level":1,"kp":"密度的概念","prompt":"一瓶矿泉水喝掉一半后，剩余水的密度","choices":["变为原来的一半","变为原来的2倍","不变","无法确定"],"answer":2,"explain":"密度是物质的一种特性，同种物质在状态、温度不变时密度不变。喝掉一半后质量和体积都减半，比值m/V不变，所以密度不变。"},
    {"id":"wl.li-L1-05","module":"wl.li","level":1,"kp":"摩擦力的影响因素","prompt":"下列做法中，为了增大摩擦的是","choices":["运动鞋鞋底刻有凹凸不平的花纹","给自行车链条加润滑油","行李箱底部装有轮子","磁悬浮列车悬浮行驶"],"answer":0,"explain":"鞋底花纹增大了接触面的粗糙程度，从而增大摩擦。加润滑油使接触面分离、装轮子变滑动为滚动、磁悬浮使接触面分离，都是减小摩擦。"},
    {"id":"wl.li-L2-01","module":"wl.li","level":2,"kp":"速度计算","prompt":"一辆汽车以72 km/h的速度匀速行驶10 min，通过的路程是","choices":["720 km","7.2 km","1.2 km","12 km"],"answer":3,"explain":"10 min=1/6 h，s=vt=72 km/h×1/6 h=12 km。也可换算：72 km/h=20 m/s，s=20 m/s×600 s=12000 m=12 km。直接用72×10得720 km是单位没有统一。"},
    {"id":"wl.li-L2-02","module":"wl.li","level":2,"kp":"二力平衡与摩擦力","prompt":"小明用10 N的水平推力推放在水平地面上的箱子，箱子没有被推动。此时箱子受到的摩擦力","choices":["小于10 N","等于10 N","大于10 N","等于0"],"answer":1,"explain":"箱子静止，处于平衡状态，水平方向的推力与静摩擦力是一对平衡力，大小相等，摩擦力为10 N。很多同学认为“推不动是因为推力小于摩擦力”，这是错误的。"},
    {"id":"wl.li-L2-03","module":"wl.li","level":2,"kp":"力与运动的关系","prompt":"关于力和运动的关系，下列说法正确的是","choices":["物体不受力时，一定处于静止状态","物体受到力的作用，运动状态一定改变","力是改变物体运动状态的原因","运动的物体如果不受力，会慢慢停下来"],"answer":2,"explain":"由牛顿第一定律，力不是维持运动的原因，而是改变运动状态的原因。不受力的物体可能静止也可能做匀速直线运动；受平衡力时运动状态不变；运动物体不受力将做匀速直线运动，“慢慢停下”是受到了阻力。"},
    {"id":"wl.li-L2-04","module":"wl.li","level":2,"kp":"密度计算","prompt":"某金属块的质量为54 g，体积为20 cm³，它的密度是","choices":["2.7 kg/m³","2.7×10^{3} kg/m³","0.37×10^{3} kg/m³","1.08×10^{3} kg/m³"],"answer":1,"explain":"ρ=m/V=54 g/20 cm³=2.7 g/cm³=2.7×10^{3} kg/m³（1 g/cm³=10^{3} kg/m³）。2.7 kg/m³是单位换算错误；0.37是把V/m算成了密度。"},
    {"id":"wl.li-L2-05","module":"wl.li","level":2,"kp":"天平的使用","prompt":"关于托盘天平的使用，下列说法正确的是","choices":["调节横梁平衡时，指针偏向分度盘左侧，应将平衡螺母向右调","称量时指针偏向分度盘左侧，应将平衡螺母向右调","称量时应将物体放在右盘，砝码放在左盘","加减砝码时可以用手直接拿取"],"answer":0,"explain":"调平时“左偏右调”，指针偏左说明左边重，平衡螺母向右调。称量过程中不能再调平衡螺母，应加砝码或向右移游码；应“左物右码”；砝码要用镊子夹取，防止生锈。"},
    {"id":"wl.li-L2-06","module":"wl.li","level":2,"kp":"平衡力与相互作用力","prompt":"一本书静止放在水平桌面上，下列说法正确的是","choices":["书对桌面的压力和桌面对书的支持力是一对平衡力","书受到的重力和书对桌面的压力是一对相互作用力","书受到的重力和桌面对书的支持力是一对平衡力","书受到的重力和桌面对书的支持力是一对相互作用力"],"answer":2,"explain":"重力和支持力都作用在书上，大小相等、方向相反、在同一直线上，是平衡力。压力和支持力作用在两个物体上，是相互作用力；重力和压力方向相同，既不是平衡力也不是相互作用力。"},
    {"id":"wl.li-L3-01","module":"wl.li","level":3,"kp":"平均速度","prompt":"小明从家到学校，前一半路程的平均速度为4 m/s，后一半路程的平均速度为6 m/s，则全程的平均速度为","choices":["5 m/s","5.2 m/s","10 m/s","4.8 m/s"],"answer":3,"explain":"设每半程为s，所用时间t₁=s/4，t₂=s/6，总时间t=5s/12。全程平均速度v=2s/t=2s÷(5s/12)=4.8 m/s。平均速度是总路程除以总时间，不是速度的平均值5 m/s。"},
    {"id":"wl.li-L3-02","module":"wl.li","level":3,"kp":"密度测量误差分析","prompt":"小红测盐水密度：先测空烧杯质量，再测烧杯和盐水的总质量，然后把盐水全部倒入量筒中测体积。用这种方法测得的密度","choices":["偏大，因为烧杯中残留盐水，测得的体积偏小","偏小，因为烧杯中残留盐水，测得的体积偏小","偏小，因为烧杯中残留盐水，测得的质量偏小","准确，因为每个量都是直接测得的"],"answer":0,"explain":"倒入量筒时烧杯壁上残留部分盐水，量筒测得的体积比实际偏小，而质量是两次称量之差，就是全部盐水的质量，并没有测错，由ρ=m/V知密度偏大。改进：先测烧杯和盐水总质量，倒入部分到量筒测体积，再测剩余质量。"},
    {"id":"wl.li-L3-03","module":"wl.li","level":3,"kp":"二力平衡与摩擦力","prompt":"木块在5 N的水平拉力作用下，在水平桌面上做匀速直线运动。若拉力增大到8 N，木块受到的摩擦力大小和木块的运动情况是","choices":["8 N，木块做匀速直线运动","8 N，木块做加速运动","3 N，木块做加速运动","5 N，木块做加速运动"],"answer":3,"explain":"匀速运动时滑动摩擦力f=F=5 N。滑动摩擦力只与压力和接触面粗糙程度有关，拉力增大后这两者不变，摩擦力仍为5 N。此时拉力大于摩擦力，合力向前，木块做加速运动。"},
    {"id":"wl.li-L3-04","module":"wl.li","level":3,"kp":"s-t图像","stem":"甲、乙两辆小车同时从同一地点出发，沿平直公路向东运动，它们的s-t图像如图所示。","prompt":"下列说法正确的是","choices":["经过6 s，两车相距12 m；以甲车为参照物，乙车向东运动","经过6 s，两车相距12 m；以甲车为参照物，乙车向西运动","甲车的速度是乙车速度的2倍","经过6 s，两车相距24 m"],"answer":1,"explain":"由图：v甲=12 m/4 s=3 m/s，v乙=6 m/6 s=1 m/s，甲是乙的3倍。6 s时甲行驶18 m，乙行驶6 m，相距12 m。两车都向东，甲更快，以甲为参照物，乙相对甲向后（向西）运动。","svg":"<svg viewBox=\"0 0 320 225\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><line x1=\"40\" y1=\"200\" x2=\"300\" y2=\"200\"/><line x1=\"40\" y1=\"200\" x2=\"40\" y2=\"10\"/><polyline points=\"294,196 300,200 294,204\"/><polyline points=\"36,16 40,10 44,16\"/><line x1=\"40\" y1=\"200\" x2=\"280\" y2=\"20\" stroke-width=\"2\"/><line x1=\"40\" y1=\"200\" x2=\"280\" y2=\"140\" stroke-width=\"2\"/><line x1=\"200\" y1=\"200\" x2=\"200\" y2=\"80\" stroke-dasharray=\"4 3\"/><line x1=\"40\" y1=\"80\" x2=\"200\" y2=\"80\" stroke-dasharray=\"4 3\"/><line x1=\"280\" y1=\"200\" x2=\"280\" y2=\"20\" stroke-dasharray=\"4 3\"/><line x1=\"40\" y1=\"140\" x2=\"280\" y2=\"140\" stroke-dasharray=\"4 3\"/><line x1=\"40\" y1=\"20\" x2=\"280\" y2=\"20\" stroke-dasharray=\"4 3\"/><text x=\"116\" y=\"216\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">2</text><text x=\"196\" y=\"216\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">4</text><text x=\"276\" y=\"216\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">6</text><text x=\"286\" y=\"196\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">t/s</text><text x=\"22\" y=\"145\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">6</text><text x=\"16\" y=\"85\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">12</text><text x=\"16\" y=\"25\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">18</text><text x=\"46\" y=\"16\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">s/m</text><text x=\"26\" y=\"216\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">O</text><text x=\"216\" y=\"52\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">甲</text><text x=\"250\" y=\"135\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">乙</text></svg>"},
    {"id":"wl.li-L3-05","module":"wl.li","level":3,"kp":"弹力与弹簧测力计","prompt":"甲、乙两人分别用5 N的力沿水平方向向相反方向拉同一个弹簧测力计的两端，测力计静止。此时弹簧测力计的示数为","choices":["10 N","0 N","5 N","2.5 N"],"answer":2,"explain":"弹簧测力计的示数等于作用在挂钩上的拉力，为5 N。一端固定、另一端用5 N拉时，固定端同样对测力计施加5 N的力，与本题情形相同。误以为两力相加得10 N或相互抵消得0都不对。"},
    {"id":"wl.li-L3-06","module":"wl.li","level":3,"kp":"等容法测密度","prompt":"一个空瓶的质量为200 g，装满水后总质量为700 g，装满某种液体后总质量为600 g。这种液体的密度为","choices":["0.86×10^{3} kg/m³","1.25×10^{3} kg/m³","0.8×10^{3} kg/m³","1.2×10^{3} kg/m³"],"answer":2,"explain":"瓶的容积V=m水/ρ水=(700−200) g÷1 g/cm³=500 cm³。液体质量m=600−200=400 g，ρ=400 g/500 cm³=0.8 g/cm³=0.8×10^{3} kg/m³。忘记减去瓶的质量会得到600/700≈0.86。"},
    {"id":"wl.li-L4-01","module":"wl.li","level":4,"kp":"叠加体摩擦力分析","stem":"如图所示，物块A叠放在物块B上，用水平拉力F=10 N作用在B上，使A、B一起向右做匀速直线运动。","prompt":"下列说法正确的是","choices":["A受到B对它向右的摩擦力为10 N，地面对B的摩擦力为10 N","A受到的摩擦力为5 N，地面对B的摩擦力为5 N","A受到的摩擦力为0，地面对B的摩擦力为0","A受到的摩擦力为0，地面对B的摩擦力为10 N"],"answer":3,"explain":"A随B一起匀速运动，处于平衡状态，水平方向若受摩擦力则无其他力与之平衡，所以A不受摩擦力。把A、B看作整体，水平方向拉力F与地面对B的摩擦力平衡，地面对B的摩擦力为10 N，方向向左。","svg":"<svg viewBox=\"0 0 320 170\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><line x1=\"10\" y1=\"150\" x2=\"310\" y2=\"150\"/><line x1=\"20\" y1=\"150\" x2=\"10\" y2=\"160\"/><line x1=\"50\" y1=\"150\" x2=\"40\" y2=\"160\"/><line x1=\"80\" y1=\"150\" x2=\"70\" y2=\"160\"/><line x1=\"110\" y1=\"150\" x2=\"100\" y2=\"160\"/><line x1=\"140\" y1=\"150\" x2=\"130\" y2=\"160\"/><line x1=\"170\" y1=\"150\" x2=\"160\" y2=\"160\"/><line x1=\"200\" y1=\"150\" x2=\"190\" y2=\"160\"/><line x1=\"230\" y1=\"150\" x2=\"220\" y2=\"160\"/><line x1=\"260\" y1=\"150\" x2=\"250\" y2=\"160\"/><line x1=\"290\" y1=\"150\" x2=\"280\" y2=\"160\"/><rect x=\"90\" y=\"100\" width=\"120\" height=\"50\" fill=\"currentColor\" fill-opacity=\"0.1\"/><rect x=\"115\" y=\"55\" width=\"70\" height=\"45\" fill=\"currentColor\" fill-opacity=\"0.1\"/><text x=\"144\" y=\"83\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">A</text><text x=\"144\" y=\"130\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">B</text><line x1=\"210\" y1=\"125\" x2=\"285\" y2=\"125\" stroke-width=\"2\"/><polyline points=\"277,120 285,125 277,130\"/><text x=\"290\" y=\"130\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">F</text></svg>"},
    {"id":"wl.li-L4-02","module":"wl.li","level":4,"kp":"叠加体摩擦力分析","stem":"如图所示，物块A叠放在物块B上，用水平拉力F=10 N作用在A上，使A、B一起向右做匀速直线运动。","prompt":"下列说法正确的是","choices":["B对A的摩擦力为10 N，方向向左；地面对B的摩擦力为10 N，方向向左","B对A的摩擦力为0；地面对B的摩擦力为10 N，方向向左","B对A的摩擦力为10 N，方向向右；地面对B的摩擦力为0","B对A的摩擦力为10 N，方向向左；地面对B的摩擦力为0"],"answer":0,"explain":"A匀速，水平方向拉力F与B对A的摩擦力平衡，该摩擦力为10 N向左。A对B的摩擦力是其反作用力，10 N向右；B匀速，所以地面对B的摩擦力为10 N向左。也可用整体法直接得到地面对B的摩擦力。","svg":"<svg viewBox=\"0 0 320 170\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><line x1=\"10\" y1=\"150\" x2=\"310\" y2=\"150\"/><line x1=\"20\" y1=\"150\" x2=\"10\" y2=\"160\"/><line x1=\"50\" y1=\"150\" x2=\"40\" y2=\"160\"/><line x1=\"80\" y1=\"150\" x2=\"70\" y2=\"160\"/><line x1=\"110\" y1=\"150\" x2=\"100\" y2=\"160\"/><line x1=\"140\" y1=\"150\" x2=\"130\" y2=\"160\"/><line x1=\"170\" y1=\"150\" x2=\"160\" y2=\"160\"/><line x1=\"200\" y1=\"150\" x2=\"190\" y2=\"160\"/><line x1=\"230\" y1=\"150\" x2=\"220\" y2=\"160\"/><line x1=\"260\" y1=\"150\" x2=\"250\" y2=\"160\"/><line x1=\"290\" y1=\"150\" x2=\"280\" y2=\"160\"/><rect x=\"90\" y=\"100\" width=\"120\" height=\"50\" fill=\"currentColor\" fill-opacity=\"0.1\"/><rect x=\"115\" y=\"55\" width=\"70\" height=\"45\" fill=\"currentColor\" fill-opacity=\"0.1\"/><text x=\"144\" y=\"83\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">A</text><text x=\"144\" y=\"130\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">B</text><line x1=\"185\" y1=\"77\" x2=\"265\" y2=\"77\" stroke-width=\"2\"/><polyline points=\"257,72 265,77 257,82\"/><text x=\"270\" y=\"82\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">F</text></svg>"},
    {"id":"wl.li-L4-03","module":"wl.li","level":4,"kp":"空心问题计算","prompt":"一个铁球的质量为158 g，体积为30 cm³（ρ铁=7.9 g/cm³）。下列判断正确的是","choices":["铁球是实心的","铁球是空心的，空心部分体积为10 cm³","铁球是空心的，空心部分体积为20 cm³","铁球是空心的，空心部分注满水后总质量为178 g"],"answer":1,"explain":"158 g铁的体积V铁=m/ρ=158/7.9 cm³=20 cm³＜30 cm³，所以是空心的，空心部分V=30−20=10 cm³。注满水需要水10 g，总质量168 g，不是178 g。20 cm³是铁本身的体积，不是空心体积。"},
    {"id":"wl.li-L4-04","module":"wl.li","level":4,"kp":"过桥问题","prompt":"一列长200 m的火车以20 m/s的速度匀速通过一座长1000 m的大桥。火车完全通过大桥所用的时间，以及火车全部在桥上行驶的时间分别是","choices":["50 s，50 s","60 s，50 s","50 s，40 s","60 s，40 s"],"answer":3,"explain":"完全通过：从车头上桥到车尾离桥，路程为1000+200=1200 m，t=1200/20=60 s。全部在桥上：从车尾上桥到车头离桥，路程为1000−200=800 m，t=800/20=40 s。只用桥长计算得50 s。"},
    {"id":"wl.li-L4-05","module":"wl.li","level":4,"kp":"二力平衡与摩擦力","prompt":"用30 N的水平力把重10 N的木块压在竖直墙壁上，木块静止。下列说法正确的是","choices":["压力增大到50 N时摩擦力变为50 N；木块匀速下滑时摩擦力为10 N","压力增大到50 N时摩擦力仍为10 N；减小压力使木块匀速下滑时摩擦力仍为10 N","木块受到的摩擦力为30 N，方向竖直向上","减小压力使木块匀速下滑时，摩擦力小于10 N"],"answer":1,"explain":"竖直方向木块受重力和摩擦力，静止时二者平衡，摩擦力为10 N、竖直向上，与压力大小无关，所以压力增大到50 N时仍为10 N。匀速下滑也是平衡状态，滑动摩擦力仍等于重力10 N。水平压力与墙的支持力平衡，不影响竖直方向。"},
    {"id":"wl.yaqiang-L1-01","module":"wl.yaqiang","level":1,"kp":"增大和减小压强","prompt":"下列实例中，属于增大压强的是","choices":["菜刀的刀刃磨得很锋利","书包带做得较宽","铁轨下铺设枕木","骆驼长着宽大的脚掌"],"answer":0,"explain":"刀刃锋利是在压力一定时减小受力面积来增大压强。书包带宽、铺枕木、骆驼宽大的脚掌都是通过增大受力面积来减小压强。"},
    {"id":"wl.yaqiang-L1-02","module":"wl.yaqiang","level":1,"kp":"连通器","prompt":"下列装置中，利用连通器原理工作的是","choices":["用吸管吸饮料","拦河坝设计成上窄下宽","船闸","飞机的机翼"],"answer":2,"explain":"船闸的闸室与上下游通过阀门构成上端开口、底部连通的容器，是连通器。吸管吸饮料利用大气压；拦河坝上窄下宽是因为液体压强随深度增加而增大；机翼利用流速大的地方压强小。"},
    {"id":"wl.yaqiang-L1-03","module":"wl.yaqiang","level":1,"kp":"大气压","prompt":"历史上首先测出大气压强数值的实验是","choices":["马德堡半球实验","帕斯卡裂桶实验","奥斯特实验","托里拆利实验"],"answer":3,"explain":"托里拆利实验用水银柱测出1个标准大气压约等于760 mm高水银柱产生的压强。马德堡半球实验证明了大气压的存在且很大；裂桶实验说明液体压强与深度有关；奥斯特实验发现电流的磁效应。"},
    {"id":"wl.yaqiang-L1-04","module":"wl.yaqiang","level":1,"kp":"流体压强与流速","prompt":"火车站台上设有安全线，乘客必须站在安全线以外候车，原因是列车驶过时","choices":["人与列车之间空气流速大、压强大，人容易被推离列车","人与列车之间空气流速大、压强小，人容易被“推”向列车","人与列车之间空气流速小、压强小，人容易被吸向列车","列车产生的噪声太大，会伤害人的听力"],"answer":1,"explain":"列车高速驶过时，带动人与列车之间的空气快速流动，这里流速大、压强小，而人外侧空气压强较大，压强差会把人推向列车，非常危险。这是流体压强与流速关系的应用。"},
    {"id":"wl.yaqiang-L1-05","module":"wl.yaqiang","level":1,"kp":"阿基米德原理","prompt":"将一个重5 N的物体浸没在水中，它排开的水重3 N，则物体受到的浮力为","choices":["3 N","5 N","2 N","8 N"],"answer":0,"explain":"由阿基米德原理，浸在液体中的物体所受浮力等于它排开液体所受的重力，F浮=G排=3 N。物体自身的重力5 N不等于浮力；2 N是物体浸没时弹簧测力计的示数（若用测力计拉着）。"},
    {"id":"wl.yaqiang-L2-01","module":"wl.yaqiang","level":2,"kp":"固体压强计算","prompt":"质量为60 kg的同学双脚站立在水平地面上，每只脚与地面的接触面积为200 cm²（g取10 N/kg）。他对地面的压强为","choices":["3×10^{4} Pa","1.5×10^{2} Pa","1.5×10^{4} Pa","3×10^{2} Pa"],"answer":2,"explain":"F=G=mg=600 N，双脚面积S=2×200 cm²=400 cm²=0.04 m²，p=F/S=600 N/0.04 m²=1.5×10^{4} Pa。只用一只脚的面积得3×10^{4} Pa（这是行走时的压强）；面积单位换算出错（如把400 cm²当成4 m²或把200 cm²当成2 m²）会得到1.5×10^{2} Pa或3×10^{2} Pa。"},
    {"id":"wl.yaqiang-L2-02","module":"wl.yaqiang","level":2,"kp":"液体压强计算","prompt":"潜水员潜到水下20 m深处，他受到水的压强约为（ρ水=1.0×10^{3} kg/m³，g取10 N/kg，不计大气压）","choices":["2×10^{4} Pa","2×10^{5} Pa","2×10^{6} Pa","2×10^{3} Pa"],"answer":1,"explain":"p=ρgh=1.0×10^{3} kg/m³×10 N/kg×20 m=2×10^{5} Pa。液体压强只与液体密度和深度有关，注意深度单位用m，数量级容易算错。"},
    {"id":"wl.yaqiang-L2-03","module":"wl.yaqiang","level":2,"kp":"物体浮沉条件","prompt":"把同一个鸡蛋先后放入甲、乙两杯盐水中，鸡蛋在甲杯中悬浮，在乙杯中漂浮。鸡蛋在两杯中受到的浮力F甲、F乙和两杯盐水的密度ρ甲、ρ乙的关系是","choices":["F甲=F乙，ρ甲＜ρ乙","F甲＜F乙，ρ甲＜ρ乙","F甲=F乙，ρ甲＞ρ乙","F甲＞F乙，ρ甲=ρ乙"],"answer":0,"explain":"悬浮和漂浮时浮力都等于鸡蛋的重力，所以F甲=F乙。悬浮时ρ甲=ρ蛋，漂浮时ρ乙＞ρ蛋，所以ρ甲＜ρ乙。也可以由F浮=ρ液gV排，浮力相同，乙中V排小，则ρ乙大。"},
    {"id":"wl.yaqiang-L2-04","module":"wl.yaqiang","level":2,"kp":"液体压强特点","prompt":"一个上细下粗、未装满水的密闭矿泉水瓶，先正立放在水平桌面上，再倒立放置。倒立后与正立时相比，水对瓶底部（倒立时为瓶盖）的压强p和瓶对桌面的压强p′的变化是","choices":["p变大，p′不变","p不变，p′变大","p变小，p′变大","p变大，p′变大"],"answer":3,"explain":"倒立后瓶口细，同样多的水液面变高，由p=ρgh知水对瓶盖的压强变大。瓶对桌面的压力等于瓶和水的总重，不变，而受力面积由瓶底变为瓶盖，变小，所以p′变大。"},
    {"id":"wl.yaqiang-L2-05","module":"wl.yaqiang","level":2,"kp":"称重法测浮力","prompt":"用弹簧测力计挂着一个实心物体，在空气中示数为4 N，将物体浸没在水中时示数为3 N（ρ水=1.0×10^{3} kg/m³，g取10 N/kg）。该物体的密度为","choices":["3×10^{3} kg/m³","1.33×10^{3} kg/m³","4×10^{3} kg/m³","0.25×10^{3} kg/m³"],"answer":2,"explain":"F浮=G−F示=4 N−3 N=1 N，V=V排=F浮/(ρ水g)=1×10^{-4} m³；m=G/g=0.4 kg，ρ=m/V=4×10^{3} kg/m³。快捷方法：浸没时ρ物/ρ水=G/F浮=4。"},
    {"id":"wl.yaqiang-L3-01","module":"wl.yaqiang","level":3,"kp":"大气压","prompt":"关于托里拆利实验，下列说法正确的是","choices":["换用更粗的玻璃管，水银柱的高度会变低","把实验装置搬到高山上，水银柱的高度会变高","将玻璃管稍微倾斜，管内水银柱的竖直高度不变","管内混入少量空气，水银柱的高度不变"],"answer":2,"explain":"管内水银柱产生的压强等于外界大气压，竖直高度由大气压决定，倾斜时长度变长但竖直高度不变，与管的粗细也无关。高山上气压低，水银柱变低；管内混入空气，空气产生向下的压强，水银柱会变低。"},
    {"id":"wl.yaqiang-L3-02","module":"wl.yaqiang","level":3,"kp":"液体压强特点","stem":"如图所示，甲、乙、丙三个容器的底面积相同，形状不同，分别装入质量相等的水（水均未溢出）。","prompt":"水对容器底部的压强p甲、p乙、p丙的大小关系是","choices":["p甲=p乙=p丙","p甲＞p乙＞p丙","p乙＞p甲=p丙","p甲＜p乙＜p丙"],"answer":3,"explain":"水的质量相等、体积相等，甲上口大，水面最低；丙上口小，水面最高。由p=ρgh，深度越大压强越大，所以p甲＜p乙＜p丙。误以为“水重相同、底面积相同则压强相同”，是忽略了非柱形容器中水对底部的压力不等于水重。","svg":"<svg viewBox=\"0 0 330 170\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><polygon points=\"20,140 80,140 100,40 0,40\"/><polygon points=\"20,140 80,140 89,95 11,95\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"none\"/><line x1=\"11\" y1=\"95\" x2=\"89\" y2=\"95\" stroke-dasharray=\"4 3\"/><polygon points=\"140,140 200,140 200,40 140,40\"/><polygon points=\"140,140 200,140 200,80 140,80\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"none\"/><line x1=\"140\" y1=\"80\" x2=\"200\" y2=\"80\" stroke-dasharray=\"4 3\"/><polygon points=\"260,140 320,140 300,40 280,40\"/><polygon points=\"260,140 320,140 304,60 276,60\" fill=\"currentColor\" fill-opacity=\"0.15\" stroke=\"none\"/><line x1=\"276\" y1=\"60\" x2=\"304\" y2=\"60\" stroke-dasharray=\"4 3\"/><text x=\"43\" y=\"162\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">甲</text><text x=\"163\" y=\"162\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">乙</text><text x=\"283\" y=\"162\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">丙</text></svg>"},
    {"id":"wl.yaqiang-L3-03","module":"wl.yaqiang","level":3,"kp":"漂浮条件计算","prompt":"一个木块漂浮在水面上，露出水面的体积是总体积的2/5。木块的密度为","choices":["0.6×10^{3} kg/m³","0.4×10^{3} kg/m³","1.5×10^{3} kg/m³","0.8×10^{3} kg/m³"],"answer":0,"explain":"漂浮时F浮=G，即ρ水g×(3/5)V=ρ木gV，所以ρ木=(3/5)ρ水=0.6×10^{3} kg/m³。浸入水中的是3/5，不是2/5；用露出部分计算会得到0.4×10^{3}。"},
    {"id":"wl.yaqiang-L3-04","module":"wl.yaqiang","level":3,"kp":"柱体压强p=ρgh","prompt":"一个质量分布均匀的实心正方体放在水平地面上。下列关于切割后剩余部分对地面压强的说法正确的是","choices":["沿竖直方向切去一半，剩余部分对地面的压强减半","沿竖直方向切去一半，剩余部分对地面的压强不变","沿水平方向切去一半，剩余部分对地面的压强不变","沿水平方向切去一半，剩余部分对地面的压力不变"],"answer":1,"explain":"均匀柱体对水平面的压强p=F/S=ρgh。竖直切去一半，ρ和h都不变，压强不变（压力、面积都减半）。水平切去一半，高度减半，压强减半，压力也减半。"},
    {"id":"wl.yaqiang-L3-05","module":"wl.yaqiang","level":3,"kp":"物体浮沉条件","prompt":"关于潜水艇，下列说法正确的是","choices":["潜水艇是靠改变所受浮力来实现上浮和下潜的","潜水艇浸没后继续下潜，所受浮力不变，受到海水的压强变大","潜水艇浸没后继续下潜，所受浮力变大","潜水艇漂浮在海面时，受到的浮力大于它的重力"],"answer":1,"explain":"浸没后V排不变，由F浮=ρ液gV排知浮力不变；深度增大，压强变大。潜水艇靠向水舱充水或排水改变自身重力来实现浮沉；漂浮时浮力等于重力。"},
    {"id":"wl.yaqiang-L3-06","module":"wl.yaqiang","level":3,"kp":"物体浮沉条件","prompt":"一艘轮船从长江驶入大海（ρ海水＞ρ江水），轮船受到的浮力和船身的变化是","choices":["浮力变大，船身上浮一些","浮力不变，船身下沉一些","浮力不变，船身上浮一些","浮力变小，船身下沉一些"],"answer":2,"explain":"轮船始终漂浮，浮力等于船的重力，重力不变，浮力不变。由F浮=ρ液gV排，海水密度大，V排变小，所以船身上浮一些。注意不要误认为“海水密度大，浮力就变大”。"},
    {"id":"wl.yaqiang-L4-01","module":"wl.yaqiang","level":4,"kp":"浮力与液面变化","prompt":"盛水的杯中漂浮着一块内部含有小石块的冰块。冰块全部熔化后，杯中水面将","choices":["上升","不变","无法判断","下降"],"answer":3,"explain":"熔化前整体漂浮，V排=(G冰+G石)/(ρ水g)。熔化后，冰化成的水体积恰好等于原来冰排开水的体积（G冰/(ρ水g)），而石块沉底，排开体积V石＜G石/(ρ水g)。总排开体积变小，水面下降。纯冰熔化时水面不变。"},
    {"id":"wl.yaqiang-L4-02","module":"wl.yaqiang","level":4,"kp":"浮力与液体压强综合","prompt":"底面积为200 cm²的柱形容器中装有深20 cm的水。放入一个重6 N的木块，木块漂浮且水未溢出（ρ水=1.0×10^{3} kg/m³，g取10 N/kg）。木块排开水的体积和水对容器底部压强的增加量分别是","choices":["600 cm³，300 Pa","600 cm³，2300 Pa","6000 cm³，300 Pa","300 cm³，150 Pa"],"answer":0,"explain":"漂浮时F浮=G=6 N，V排=F浮/(ρ水g)=6×10^{-4} m³=600 cm³。水面上升Δh=V排/S=600 cm³/200 cm²=3 cm，Δp=ρgΔh=1.0×10^{3}×10×0.03 Pa=300 Pa。2300 Pa是总压强，不是增加量。"},
    {"id":"wl.yaqiang-L4-03","module":"wl.yaqiang","level":4,"kp":"浮力图像综合","stem":"用弹簧测力计吊着一个实心圆柱体，从盛水烧杯的水面上方开始缓慢下降，直至完全浸没（未接触杯底）。测力计示数F与圆柱体下降高度h的关系如图所示（ρ水=1.0×10^{3} kg/m³，g取10 N/kg，忽略水面高度变化）。","prompt":"下列说法正确的是","choices":["圆柱体受到的最大浮力为12 N","圆柱体的体积为4×10^{-4} m³","圆柱体刚好浸没时，下表面受到水的压强为700 Pa","圆柱体的密度为1.5×10^{3} kg/m³"],"answer":3,"explain":"G=12 N，浸没后示数4 N，最大浮力F浮=12−4=8 N，V=F浮/(ρ水g)=8×10^{-4} m³，ρ=G/(gV)=1.5×10^{3} kg/m³。从h=3 cm开始接触水面到7 cm完全浸没，圆柱体高4 cm，刚浸没时下表面深0.04 m，压强为400 Pa，不是700 Pa。","svg":"<svg viewBox=\"0 0 320 195\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><line x1=\"40\" y1=\"170\" x2=\"290\" y2=\"170\"/><line x1=\"40\" y1=\"170\" x2=\"40\" y2=\"10\"/><polyline points=\"284,166 290,170 284,174\"/><polyline points=\"36,16 40,10 44,16\"/><polyline points=\"40,26 115,26 215,122 265,122\" stroke-width=\"2\"/><line x1=\"115\" y1=\"26\" x2=\"115\" y2=\"170\" stroke-dasharray=\"4 3\"/><line x1=\"215\" y1=\"122\" x2=\"215\" y2=\"170\" stroke-dasharray=\"4 3\"/><line x1=\"40\" y1=\"122\" x2=\"215\" y2=\"122\" stroke-dasharray=\"4 3\"/><text x=\"110\" y=\"186\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">3</text><text x=\"210\" y=\"186\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">7</text><text x=\"260\" y=\"186\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">9</text><text x=\"270\" y=\"162\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">h/cm</text><text x=\"24\" y=\"127\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">4</text><text x=\"16\" y=\"31\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">12</text><text x=\"46\" y=\"16\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">F/N</text><text x=\"26\" y=\"186\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">O</text></svg>"},
    {"id":"wl.yaqiang-L4-04","module":"wl.yaqiang","level":4,"kp":"物体浮沉条件","prompt":"把实心铁球和实心木球放入足量的水中，静止后（ρ铁＞ρ水＞ρ木），下列判断正确的是","choices":["若两球体积相等，铁球受到的浮力大；若两球质量相等，木球受到的浮力大","若两球体积相等，木球受到的浮力大；若两球质量相等，铁球受到的浮力大","无论体积还是质量相等，铁球受到的浮力都大","无论体积还是质量相等，两球受到的浮力都相等"],"answer":0,"explain":"铁球沉底，木球漂浮。体积相等时，铁球全部浸没，V排更大，铁球浮力大。质量相等时，木球漂浮F浮=G，铁球沉底F浮＜G，两球重力相等，所以木球浮力大。比较浮力要先判断浮沉状态再选方法。"},
    {"id":"wl.yaqiang-L4-05","module":"wl.yaqiang","level":4,"kp":"固体压强计算","prompt":"正方体A的边长为10 cm、重20 N，正方体B的边长为20 cm、重60 N。将A放在B的上表面中央，B放在水平地面上。A对B的压强与B对地面的压强之比为","choices":["1:4","1:3","1:1","4:1"],"answer":2,"explain":"A对B：F=20 N，受力面积为A的底面积0.01 m²，p₁=2000 Pa。B对地：F=20+60=80 N，S=0.04 m²，p₂=2000 Pa。比值为1:1。容易出错的是B对地面的压力漏加A的重力，或A对B的受力面积误用B的面积。"},
    {"id":"wl.gong-L1-01","module":"wl.gong","level":1,"kp":"做功的两个必要因素","prompt":"下列情境中，人对物体做了功的是","choices":["提着水桶在水平路面上匀速行走","将书包从地面提到桌面上","用力推汽车，汽车没有动","踢出去的足球在地面上滚动了一段距离"],"answer":1,"explain":"做功需要有力作用在物体上，且物体在力的方向上移动了距离。提书包向上，力和距离都向上，做了功。提水桶水平走，力与移动方向垂直；推车未动，没有距离；足球滚动时脚已不再施力，都不做功。"},
    {"id":"wl.gong-L1-02","module":"wl.gong","level":1,"kp":"机械能转化","prompt":"人造地球卫星沿椭圆轨道运行，从远地点向近地点运行时","choices":["重力势能增大，动能减小","重力势能减小，动能增大","重力势能和动能都增大","重力势能和动能都减小"],"answer":1,"explain":"从远地点到近地点，卫星离地高度减小，重力势能减小；速度变大，动能增大，是重力势能转化为动能。太空中几乎没有阻力，机械能守恒。"},
    {"id":"wl.gong-L1-03","module":"wl.gong","level":1,"kp":"杠杆的分类","prompt":"下列工具在正常使用时，属于省力杠杆的是","choices":["夹取物品的镊子","钓鱼竿","吃饭用的筷子","拔钉子的羊角锤"],"answer":3,"explain":"羊角锤拔钉子时动力臂大于阻力臂，是省力杠杆。镊子、钓鱼竿、筷子的动力臂都小于阻力臂，是费力杠杆，但可以省距离。"},
    {"id":"wl.gong-L1-04","module":"wl.gong","level":1,"kp":"滑轮的特点","prompt":"关于定滑轮，下列说法正确的是","choices":["不能省力，但可以改变力的方向","能省一半的力，但不能改变力的方向","既能省力，又能改变力的方向","能省距离，但不能改变力的方向"],"answer":0,"explain":"定滑轮实质是等臂杠杆，不省力也不省距离，但能改变力的方向，如旗杆顶的滑轮。动滑轮实质是动力臂为阻力臂2倍的杠杆，能省一半力，但不能改变力的方向。"},
    {"id":"wl.gong-L1-05","module":"wl.gong","level":1,"kp":"功率的概念","prompt":"关于功率，下列说法正确的是","choices":["功率越大，做功越多","机械效率越高，功率越大","功率越大，做功越快","做功时间越短，功率越大"],"answer":2,"explain":"功率是表示做功快慢的物理量，P=W/t，功率大说明做功快。做功多少还与时间有关；时间短但做功少，功率不一定大；功率与机械效率是两个不同的概念，没有必然联系。"},
    {"id":"wl.gong-L2-01","module":"wl.gong","level":2,"kp":"功和功率计算","prompt":"用50 N的水平推力推着重200 N的箱子，在水平地面上匀速前进4 m，用时10 s。推力做的功和功率分别是","choices":["800 J，80 W","1000 J，100 W","200 J，2000 W","200 J，20 W"],"answer":3,"explain":"W=Fs=50 N×4 m=200 J，P=W/t=200 J/10 s=20 W。重力方向竖直向下，箱子水平运动，重力不做功，不能用200 N×4 m=800 J；功率用乘法得2000 W是公式记错。"},
    {"id":"wl.gong-L2-02","module":"wl.gong","level":2,"kp":"杠杆平衡条件","stem":"如图所示，杠杆在水平位置平衡，每格长度相等，每个钩码质量相同：支点O左侧第3格挂2个钩码，右侧第2格挂3个钩码。","prompt":"若在两侧钩码下方再各加挂一个相同的钩码，杠杆将","choices":["左端下沉","右端下沉","仍保持平衡","无法确定"],"answer":0,"explain":"设每个钩码重G、每格长L。原来2G×3L=3G×2L，平衡。各加一个后，左边3G×3L=9GL，右边4G×2L=8GL，左边力与力臂的乘积大，左端下沉。不能认为“两边加的一样多仍平衡”。","svg":"<svg viewBox=\"0 0 360 140\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><rect x=\"40\" y=\"56\" width=\"280\" height=\"8\" fill=\"currentColor\" fill-opacity=\"0.15\"/><line x1=\"145\" y1=\"56\" x2=\"145\" y2=\"64\"/><line x1=\"215\" y1=\"56\" x2=\"215\" y2=\"64\"/><line x1=\"110\" y1=\"56\" x2=\"110\" y2=\"64\"/><line x1=\"250\" y1=\"56\" x2=\"250\" y2=\"64\"/><line x1=\"75\" y1=\"56\" x2=\"75\" y2=\"64\"/><line x1=\"285\" y1=\"56\" x2=\"285\" y2=\"64\"/><line x1=\"40\" y1=\"56\" x2=\"40\" y2=\"64\"/><line x1=\"320\" y1=\"56\" x2=\"320\" y2=\"64\"/><polygon points=\"180,64 168,86 192,86\"/><text x=\"176\" y=\"102\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">O</text><line x1=\"75\" y1=\"64\" x2=\"75\" y2=\"80\"/><circle cx=\"75\" cy=\"87\" r=\"7\"/><line x1=\"75\" y1=\"94\" x2=\"75\" y2=\"96\"/><circle cx=\"75\" cy=\"103\" r=\"7\"/><line x1=\"250\" y1=\"64\" x2=\"250\" y2=\"80\"/><circle cx=\"250\" cy=\"87\" r=\"7\"/><line x1=\"250\" y1=\"94\" x2=\"250\" y2=\"96\"/><circle cx=\"250\" cy=\"103\" r=\"7\"/><line x1=\"250\" y1=\"110\" x2=\"250\" y2=\"112\"/><circle cx=\"250\" cy=\"119\" r=\"7\"/></svg>"},
    {"id":"wl.gong-L2-03","module":"wl.gong","level":2,"kp":"滑轮组的计算","prompt":"用滑轮组匀速提升重270 N的物体，承担物重的绳子有3段，动滑轮重30 N，不计绳重和摩擦。物体升高2 m时，绳子自由端的拉力和移动的距离分别是","choices":["90 N，6 m","150 N，4 m","100 N，6 m","100 N，2 m"],"answer":2,"explain":"F=(G物+G动)/n=(270+30) N/3=100 N，绳端移动距离s=nh=3×2 m=6 m。忽略动滑轮重会得到90 N；把绳端移动距离当成物体升高的距离会得到2 m。"},
    {"id":"wl.gong-L2-04","module":"wl.gong","level":2,"kp":"斜面机械效率","prompt":"沿长5 m、高1 m的斜面，用250 N的拉力把重1000 N的物体从底端匀速拉到顶端。该斜面的机械效率为","choices":["25%","80%","75%","20%"],"answer":1,"explain":"W有=Gh=1000 N×1 m=1000 J，W总=Fs=250 N×5 m=1250 J，η=W有/W总=1000/1250=80%。注意有用功用物重乘高度，总功用拉力乘斜面长度，两者不能混用。"},
    {"id":"wl.gong-L2-05","module":"wl.gong","level":2,"kp":"动能影响因素实验","prompt":"在“探究物体的动能跟哪些因素有关”的实验中，让小球从斜面上由静止滚下，撞击水平面上的木块。下列说法正确的是","choices":["让同一小球从斜面的不同高度滚下，是为了探究动能与速度的关系","该实验探究的是木块的动能大小与哪些因素有关","让质量不同的小球从斜面的不同高度滚下，可以探究动能与质量的关系","若水平面绝对光滑，实验更容易得出结论"],"answer":0,"explain":"同一小球质量不变，高度不同则到达水平面的速度不同，探究的是动能与速度的关系。实验研究的是小球的动能，木块被撞得越远说明小球的动能越大（转换法）；探究质量的影响时要控制速度相同，即从同一高度滚下；水平面光滑时木块会一直运动，无法比较距离。"},
    {"id":"wl.gong-L2-06","module":"wl.gong","level":2,"kp":"功率估测","prompt":"质量为50 kg的同学用20 s从一楼走到三楼，每层楼高3 m（g取10 N/kg）。他上楼的功率约为","choices":["15 W","1500 W","225 W","150 W"],"answer":3,"explain":"从一楼到三楼只上升了2层，h=6 m，W=Gh=500 N×6 m=3000 J，P=W/t=3000 J/20 s=150 W。误按3层计算得225 W，是常见错误。"},
    {"id":"wl.gong-L3-01","module":"wl.gong","level":3,"kp":"滑轮组机械效率","prompt":"用承担物重绳子段数为2的滑轮组，以250 N的拉力匀速提升重400 N的物体（不计绳重和摩擦）。下列说法正确的是","choices":["机械效率为80%，若提升600 N的物体，机械效率不变","机械效率为62.5%，动滑轮重为100 N","机械效率为80%，若提升600 N的物体，机械效率将变大","动滑轮重为150 N，若提升600 N的物体，机械效率将变小"],"answer":2,"explain":"η=G/(nF)=400/(2×250)=80%。G动=nF−G=500−400=100 N。提升600 N时η=600/(600+100)≈85.7%，变大。同一滑轮组，额外功不变，物重越大机械效率越高。"},
    {"id":"wl.gong-L3-02","module":"wl.gong","level":3,"kp":"机械能转化","prompt":"一个小球从高处自由下落，落到竖直放置的轻弹簧上，将弹簧压缩到最短（不计空气阻力）。从小球接触弹簧到弹簧压缩到最短的过程中","choices":["小球的速度一直减小","小球的速度先增大后减小","小球刚接触弹簧时动能最大","弹簧压缩到最短时，小球受力平衡"],"answer":1,"explain":"刚接触时弹力小于重力，小球仍加速；弹力增大到等于重力时速度最大、动能最大；之后弹力大于重力，小球减速，到最低点速度为零，此时弹力大于重力，受力不平衡。所以速度先增大后减小。"},
    {"id":"wl.gong-L3-03","module":"wl.gong","level":3,"kp":"功率P=Fv","prompt":"一辆汽车发动机的功率为60 kW，在平直公路上以72 km/h的速度匀速行驶，汽车受到的阻力为","choices":["833 N","4320 N","300 N","3000 N"],"answer":3,"explain":"v=72 km/h=20 m/s，由P=Fv得F=P/v=60000 W/20 m/s=3000 N，匀速行驶时阻力f=F=3000 N。不把速度换算成m/s，用60000÷72会得到833 N。"},
    {"id":"wl.gong-L3-04","module":"wl.gong","level":3,"kp":"杠杆动态分析","prompt":"一根质量分布均匀的木棒一端着地，用始终竖直向上的力F作用在另一端，将木棒从水平位置缓慢抬起（未到竖直位置）。在此过程中，力F的大小","choices":["变大","变小","不变","先变大后变小"],"answer":2,"explain":"着地端为支点，重力作用在木棒中点。抬起过程中，动力F竖直，阻力（重力）竖直，两者的力臂都等于各自作用点到支点的水平距离，同乘cosθ，比值始终为2:1，所以F=G/2保持不变。若F始终垂直于木棒，则F会变小。"},
    {"id":"wl.gong-L3-05","module":"wl.gong","level":3,"kp":"斜面机械效率","prompt":"沿长5 m、高1 m的斜面，用250 N的拉力把重1000 N的物体从底端匀速拉到顶端。物体受到斜面的摩擦力为","choices":["50 N","250 N","200 N","0"],"answer":0,"explain":"W总=Fs=1250 J，W有=Gh=1000 J，额外功W额=250 J，是克服摩擦做的功，f=W额/s=250 J/5 m=50 N。物体在斜面上匀速运动时，拉力不等于摩擦力，因为还要克服重力沿斜面的作用。"},
    {"id":"wl.gong-L3-06","module":"wl.gong","level":3,"kp":"机械能转化","prompt":"从同一高度以大小相同的速度分别将三个相同的小球竖直上抛、斜向上抛出和水平抛出，不计空气阻力。三个小球落地时速度的大小","choices":["竖直上抛的最大","一样大","水平抛出的最大","斜向上抛出的最大"],"answer":1,"explain":"不计空气阻力，机械能守恒。三球抛出时高度相同、速度大小相同，机械能相等；落地时重力势能也相等，所以动能相等，速度大小相等。速度方向不同，但大小与抛出方向无关。"},
    {"id":"wl.gong-L4-01","module":"wl.gong","level":4,"kp":"杠杆最小力","stem":"如图所示，轻质杠杆OA长1.2 m，可绕O点转动，与水平方向成30°角保持静止。在OA的中点B处挂一个重40 N的物体。","prompt":"在A端施加一个力使杠杆在图示位置平衡，所需的最小力的大小和方向是","choices":["20 N，竖直向上","10√3 N（约17.3 N），垂直于OA向上","20 N，垂直于OA向上","40 N，竖直向上"],"answer":1,"explain":"阻力臂为OB的水平投影：0.6 m×cos30°=0.3√3 m。动力臂最大是以OA为力臂，即力垂直于OA向上，L=1.2 m。F×1.2=40×0.3√3，F=10√3 N≈17.3 N。若力竖直向上，力臂为1.2cos30° m，F=20 N，能平衡但不是最小。","svg":"<svg viewBox=\"0 0 300 180\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><line x1=\"40\" y1=\"150\" x2=\"248\" y2=\"30\" stroke-width=\"4\"/><polygon points=\"40,150 28,170 52,170\"/><line x1=\"40\" y1=\"150\" x2=\"130\" y2=\"150\" stroke-dasharray=\"4 3\"/><path d=\"M 80 150 A 40 40 0 0 0 74.6 130\"/><text x=\"86\" y=\"144\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">30°</text><line x1=\"144\" y1=\"90\" x2=\"144\" y2=\"125\"/><rect x=\"129\" y=\"125\" width=\"30\" height=\"24\" fill=\"currentColor\" fill-opacity=\"0.15\"/><text x=\"18\" y=\"150\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">O</text><text x=\"124\" y=\"80\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">B</text><text x=\"254\" y=\"30\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">A</text></svg>"},
    {"id":"wl.gong-L4-02","module":"wl.gong","level":4,"kp":"滑轮组的计算","prompt":"用滑轮组水平拉动地面上的物体A，承担拉物体的绳子有3段。A受到地面的摩擦力为120 N，滑轮组的机械效率为80%，A以0.2 m/s的速度匀速运动。绳子自由端的拉力F和拉力的功率分别是","choices":["50 N，30 W","40 N，24 W","50 N，10 W","40 N，8 W"],"answer":0,"explain":"水平拉动时有用功是克服摩擦做的功：η=fs物/(F×3s物)=f/(3F)，F=120/(3×0.8) N=50 N。绳端速度v=3×0.2 m/s=0.6 m/s，P=Fv=30 W。忽略效率得40 N；用物体速度算功率得10 W。"},
    {"id":"wl.gong-L4-03","module":"wl.gong","level":4,"kp":"机械能转化","stem":"① 跳伞运动员匀速下落时，动能不变，机械能减小\n② 蹦床运动员从最高点下落到刚接触蹦床的过程中（不计空气阻力），重力势能转化为动能\n③ 单摆的小球摆到最高点时，若一切外力突然消失，小球将保持静止\n④ 人造地球卫星在近地点时动能最小","prompt":"以上说法中正确的是","choices":["只有①②③","只有①②④","只有②③","只有①③④"],"answer":0,"explain":"①速度不变动能不变，高度降低势能减小，机械能减小，正确；②下落时高度减小速度增大，正确；③最高点速度为零，外力消失后保持静止，正确；④近地点速度最大，动能最大，错误。","fixed":true},
    {"id":"wl.gong-L4-04","module":"wl.gong","level":4,"kp":"杠杆与浮力综合","prompt":"轻质杠杆AB可绕支点O转动，AO:OB=1:2。A端用细线挂一个重30 N的实心物体并使其浸没在水中，B端挂一个重10 N的物体，杠杆在水平位置平衡（ρ水=1.0×10^{3} kg/m³，g取10 N/kg）。浸没在水中的物体的密度为","choices":["1.5×10^{3} kg/m³","2×10^{3} kg/m³","1.2×10^{3} kg/m³","3×10^{3} kg/m³"],"answer":3,"explain":"由杠杆平衡条件F_{A}×OA=10 N×OB，F_{A}=20 N，即细线拉力20 N。物体受浮力F浮=G−F_{A}=10 N，V=F浮/(ρ水g)=1×10^{-3} m³，m=3 kg，ρ=3×10^{3} kg/m³。浸没时ρ物/ρ水=G/F浮=3也可以速算。"},
    {"id":"wl.gong-L4-05","module":"wl.gong","level":4,"kp":"滑轮组机械效率","prompt":"工人用承担物重绳子段数为2的滑轮组，以500 N的拉力将重900 N的建材以0.1 m/s的速度匀速提升（不计绳重和摩擦）。下列说法正确的是","choices":["滑轮组的机械效率为80%","动滑轮重为50 N","拉力的功率为100 W","绳子自由端移动的速度为0.1 m/s"],"answer":2,"explain":"绳端速度v=2×0.1 m/s=0.2 m/s，P=Fv=500×0.2 W=100 W。η=G/(nF)=900/1000=90%；G动=nF−G=1000−900=100 N。绳端速度是物体速度的2倍，用0.1 m/s计算功率会得50 W。"},
    {"id":"wl.dianlu-L1-01","module":"wl.dianlu","level":1,"kp":"电荷与摩擦起电","prompt":"用丝绸摩擦过的玻璃棒带正电，这是因为在摩擦过程中","choices":["玻璃棒得到了电子","玻璃棒创造了正电荷","丝绸失去了电子","玻璃棒失去了电子"],"answer":3,"explain":"摩擦起电的实质是电子的转移，不是创造了电荷。玻璃棒束缚电子的能力弱，摩擦时失去电子而带正电，丝绸得到电子带等量的负电。"},
    {"id":"wl.dianlu-L1-02","module":"wl.dianlu","level":1,"kp":"导体和绝缘体","prompt":"下列各组物体中，通常情况下全部属于导体的是","choices":["塑料、橡胶、陶瓷","铁丝、玻璃、人体","铜丝、石墨、盐水","空气、油、大地"],"answer":2,"explain":"金属、石墨、酸碱盐的水溶液、人体、大地通常是导体。塑料、橡胶、陶瓷、玻璃、空气、油通常是绝缘体。每组都要逐个判断，有一个是绝缘体就不能选。"},
    {"id":"wl.dianlu-L1-03","module":"wl.dianlu","level":1,"kp":"串并联电流电压规律","prompt":"两只小灯泡L₁、L₂串联在电路中，闭合开关后L₁比L₂亮。通过两灯的电流I₁、I₂的关系是","choices":["I₁=I₂","I₁＞I₂","I₁＜I₂","无法确定"],"answer":0,"explain":"串联电路中电流处处相等，与灯的亮暗无关。灯的亮度由实际功率决定，L₁更亮是因为它的电阻更大、两端电压更大，不是电流更大。"},
    {"id":"wl.dianlu-L1-04","module":"wl.dianlu","level":1,"kp":"电表的使用","prompt":"关于电流表和电压表的使用，下列说法正确的是","choices":["电压表必须与被测用电器串联","电压表应与被测用电器并联","电流表可以直接接在电源两极上","电流应从电表的负接线柱流入"],"answer":1,"explain":"电压表与被测用电器并联，电流表与被测用电器串联。电流表电阻很小，直接接在电源两极会造成短路烧坏电表；两种电表都应让电流从正接线柱流入、负接线柱流出。"},
    {"id":"wl.dianlu-L1-05","module":"wl.dianlu","level":1,"kp":"电阻的影响因素","prompt":"关于导体的电阻，下列说法正确的是","choices":["由R=U/I可知，导体的电阻与它两端的电压成正比","导体中没有电流通过时，它的电阻为零","材料和长度相同的导线，越粗电阻越大","导体的电阻与它两端的电压和通过的电流无关"],"answer":3,"explain":"电阻是导体本身的性质，由材料、长度、横截面积和温度决定，与电压、电流无关，R=U/I只是计算方法。没有电流时电阻依然存在；材料和长度相同时，横截面积越大电阻越小。"},
    {"id":"wl.dianlu-L2-01","module":"wl.dianlu","level":2,"kp":"欧姆定律计算","prompt":"一个定值电阻两端电压为3 V时，通过的电流为0.3 A；当它两端电压增大到6 V时，它的电阻和通过它的电流分别是","choices":["20 Ω，0.3 A","10 Ω，0.3 A","10 Ω，0.6 A","20 Ω，0.6 A"],"answer":2,"explain":"R=U/I=3 V/0.3 A=10 Ω。电阻不随电压改变，电压为6 V时仍为10 Ω，I=6 V/10 Ω=0.6 A。认为电压加倍电阻也加倍是错误的。"},
    {"id":"wl.dianlu-L2-02","module":"wl.dianlu","level":2,"kp":"串联分压","prompt":"电阻R₁=10 Ω与R₂=20 Ω串联在电压为6 V的电源两端，R₁两端的电压为","choices":["2 V","4 V","3 V","6 V"],"answer":0,"explain":"串联电流I=U/(R₁+R₂)=6 V/30 Ω=0.2 A，U₁=IR₁=2 V。串联电路中电压与电阻成正比，U₁:U₂=1:2，R₁分得总电压的1/3。4 V是R₂两端的电压。"},
    {"id":"wl.dianlu-L2-03","module":"wl.dianlu","level":2,"kp":"并联电路计算","prompt":"电阻R₁=10 Ω与R₂=15 Ω并联在电压为6 V的电源两端，干路中的电流为","choices":["0.24 A","1 A","0.6 A","0.4 A"],"answer":1,"explain":"并联电路各支路电压都等于6 V，I₁=6/10 A=0.6 A，I₂=6/15 A=0.4 A，干路I=I₁+I₂=1 A。用串联方法把电阻相加得6/25=0.24 A是错误的。"},
    {"id":"wl.dianlu-L2-04","module":"wl.dianlu","level":2,"kp":"电路故障判断","prompt":"灯L₁、L₂串联，闭合开关后两灯都不亮。用电压表测L₁两端电压，示数接近电源电压；测L₂两端电压，示数为0。电路的故障可能是","choices":["L₁断路","L₁短路","L₂断路","L₂短路"],"answer":0,"explain":"两灯都不亮，说明电路断路（若一灯短路，另一灯会亮）。电压表接L₁两端有接近电源电压的示数，说明电压表通过L₂与电源连通，断点在L₁处。若L₂断路，测L₁时示数应为0。"},
    {"id":"wl.dianlu-L2-05","module":"wl.dianlu","level":2,"kp":"滑动变阻器","prompt":"关于滑动变阻器，下列说法正确的是","choices":["同时接下面两个接线柱，移动滑片也能改变电阻","它可以直接改变电源电压","闭合开关前，应将滑片移到阻值最小处","它是通过改变接入电路中电阻丝的长度来改变电阻的"],"answer":3,"explain":"滑动变阻器靠改变接入电路的电阻丝长度改变电阻，接线要“一上一下”。同时接下面两个接线柱相当于定值电阻（最大阻值）；它改变的是电路中的电流和部分电压，不改变电源电压；闭合开关前滑片应移到阻值最大处，保护电路。"},
    {"id":"wl.dianlu-L3-01","module":"wl.dianlu","level":3,"kp":"动态电路分析","prompt":"定值电阻R₁与滑动变阻器R₂串联在电源电压不变的电路中，电流表测电路中的电流，电压表并联在R₂两端。闭合开关，移动滑片使R₂接入电路的阻值变大，则","choices":["电流表示数变大，电压表示数变小","电流表示数变小，电压表示数变大","电流表示数变小，电压表示数变小","电流表示数变大，电压表示数变大"],"answer":1,"explain":"R₂变大，总电阻变大，电流I=U/(R₁+R₂)变小；R₁两端电压U₁=IR₁变小，R₂两端电压U₂=U−U₁变大。注意不能直接用U₂=IR₂判断（I变小、R₂变大，无法确定），要借助定值电阻。"},
    {"id":"wl.dianlu-L3-02","module":"wl.dianlu","level":3,"kp":"动态电路分析","prompt":"定值电阻R₁与滑动变阻器R₂串联在电源电压不变的电路中，电流表测电路中的电流，电压表并联在R₁两端。闭合开关，移动滑片使R₂接入电路的阻值变大，则","choices":["电压表示数变大，电压表与电流表示数的比值不变","电压表示数变小，电压表与电流表示数的比值变大","电压表示数变小，电压表与电流表示数的比值不变","电压表示数不变，电流表示数变小"],"answer":2,"explain":"R₂变大，总电阻变大，电流变小，R₁两端电压U₁=IR₁变小。电压表与电流表示数之比U₁/I等于R₁，是定值，不变。分析“比值”时要想清楚它对应哪个电阻。"},
    {"id":"wl.dianlu-L3-03","module":"wl.dianlu","level":3,"kp":"伏安法测电阻","prompt":"用伏安法测小灯泡的电阻，测了三组数据，发现灯泡两端电压越大，算出的电阻越大。下列说法正确的是","choices":["实验中有测量错误，应重新测量","灯丝电阻随电压增大而增大，与温度无关","灯丝电阻随温度升高而增大，不应求三次电阻的平均值","应把三次电阻的平均值作为灯泡的电阻，以减小误差"],"answer":2,"explain":"电压越大，电流越大，灯丝温度越高，电阻越大，这是灯丝电阻受温度影响，不是测量错误，也不是电压决定电阻。灯丝电阻本身在变化，求平均值没有意义；测定值电阻时才多次测量求平均值减小误差。"},
    {"id":"wl.dianlu-L3-04","module":"wl.dianlu","level":3,"kp":"U-I图像","stem":"甲、乙两个定值电阻的I-U图像如图所示。","prompt":"将甲、乙串联接在某电源上，测得电路中电流为0.2 A，则电源电压为","choices":["1 V","3 V","2 V","4.5 V"],"answer":1,"explain":"由图：R甲=3 V/0.6 A=5 Ω，R乙=3 V/0.3 A=10 Ω。串联电流均为0.2 A，U甲=1 V，U乙=2 V，电源电压U=1 V+2 V=3 V。只算一个电阻两端的电压就会选1 V或2 V。","svg":"<svg viewBox=\"0 0 280 205\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><line x1=\"40\" y1=\"180\" x2=\"260\" y2=\"180\"/><line x1=\"40\" y1=\"180\" x2=\"40\" y2=\"10\"/><polyline points=\"254,176 260,180 254,184\"/><polyline points=\"36,16 40,10 44,16\"/><line x1=\"40\" y1=\"180\" x2=\"220\" y2=\"30\" stroke-width=\"2\"/><line x1=\"40\" y1=\"180\" x2=\"220\" y2=\"105\" stroke-width=\"2\"/><line x1=\"220\" y1=\"30\" x2=\"220\" y2=\"180\" stroke-dasharray=\"4 3\"/><line x1=\"40\" y1=\"30\" x2=\"220\" y2=\"30\" stroke-dasharray=\"4 3\"/><line x1=\"40\" y1=\"105\" x2=\"220\" y2=\"105\" stroke-dasharray=\"4 3\"/><line x1=\"100\" y1=\"176\" x2=\"100\" y2=\"180\"/><line x1=\"160\" y1=\"176\" x2=\"160\" y2=\"180\"/><text x=\"96\" y=\"196\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">1</text><text x=\"156\" y=\"196\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">2</text><text x=\"216\" y=\"196\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">3</text><text x=\"244\" y=\"172\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">U/V</text><text x=\"10\" y=\"110\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">0.3</text><text x=\"10\" y=\"35\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">0.6</text><text x=\"46\" y=\"16\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">I/A</text><text x=\"26\" y=\"196\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">O</text><text x=\"156\" y=\"62\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">甲</text><text x=\"226\" y=\"110\" font-size=\"14\" fill=\"currentColor\" stroke=\"none\">乙</text></svg>"},
    {"id":"wl.dianlu-L3-05","module":"wl.dianlu","level":3,"kp":"并联电路特点","prompt":"灯L₁、L₂并联接在电源电压不变的电路中，电流表接在干路上，开关S只控制L₂所在支路。原来S断开，闭合S后","choices":["电流表示数不变，L₁变暗","电流表示数变大，L₁变暗","电流表示数变小，L₁亮度不变","电流表示数变大，L₁亮度不变"],"answer":3,"explain":"并联各支路互不影响，L₁两端电压始终等于电源电压，通过它的电流不变，亮度不变。闭合S后多了一条L₂支路，干路电流等于各支路电流之和，所以电流表示数变大。"},
    {"id":"wl.dianlu-L3-06","module":"wl.dianlu","level":3,"kp":"动态电路分析","prompt":"酒精测试仪的原理：气敏电阻R的阻值随酒精气体浓度增大而减小，R与定值电阻R₀串联在电源电压不变的电路中，电压表并联在R₀两端。当被测者呼出的酒精气体浓度增大时","choices":["电路中电流变大，电压表示数变大","电路中电流变小，电压表示数变小","电路中电流变大，电压表示数变小","电路中电流变小，电压表示数变大"],"answer":0,"explain":"浓度增大，R减小，总电阻减小，电流I=U/(R+R₀)变大；R₀两端电压U₀=IR₀变大，即电压表示数变大。若电压表并联在气敏电阻R两端，示数则会变小。"},
    {"id":"wl.dianlu-L4-01","module":"wl.dianlu","level":4,"kp":"滑动变阻器取值范围","prompt":"电源电压为6 V且不变，定值电阻R₁=10 Ω与滑动变阻器R₂（最大阻值50 Ω）串联，电流表量程为0～0.6 A，电压表量程为0～3 V并联在R₁两端。为保证电路安全，R₂接入电路的阻值范围是","choices":["0～50 Ω","0～10 Ω","10 Ω～50 Ω","20 Ω～50 Ω"],"answer":2,"explain":"电压表限制：U₁≤3 V，则I≤3 V/10 Ω=0.3 A（此时电流表也安全），R总≥6 V/0.3 A=20 Ω，R₂≥10 Ω。R₂越大电流越小，各表都安全，所以最大可取50 Ω。只考虑电流表会误得R₂最小为0。"},
    {"id":"wl.dianlu-L4-02","module":"wl.dianlu","level":4,"kp":"欧姆定律综合计算","prompt":"定值电阻R₁与滑动变阻器R₂串联，电源电压不变，电压表测R₂两端电压。滑片在一端时R₂接入阻值为0，电流表示数为0.6 A；滑片在另一端时R₂接入最大阻值，电流表示数为0.2 A，电压表示数为4 V。电源电压和R₁的阻值分别是","choices":["4 V，10 Ω","6 V，10 Ω","6 V，20 Ω","8 V，20 Ω"],"answer":1,"explain":"R₂最大阻值=4 V/0.2 A=20 Ω。电源电压不变：0.6 A×R₁=0.2 A×(R₁+20 Ω)，解得R₁=10 Ω，U=0.6 A×10 Ω=6 V。也可用第二种状态：U=4 V+0.2 A×10 Ω=6 V。把电压表示数4 V当作电源电压是常见错误。"},
    {"id":"wl.dianlu-L4-03","module":"wl.dianlu","level":4,"kp":"电路故障判断","prompt":"灯L₁、L₂并联，电流表测通过L₁的电流，电压表测电源电压。闭合开关，两灯都发光；一段时间后其中一盏灯熄灭，而电流表和电压表示数都不变。产生这一现象的原因可能是","choices":["L₁断路","L₂短路","L₁短路","L₂断路"],"answer":3,"explain":"并联电路中若有一灯短路，会造成电源短路，两灯都熄灭、电压表示数为0，所以排除短路。L₁断路时电流表示数变为0；L₂断路时L₁支路不受影响，电流表、电压表示数都不变，符合题意。"},
    {"id":"wl.dianlu-L4-04","module":"wl.dianlu","level":4,"kp":"串并联比例计算","prompt":"电阻R₁、R₂并联时，干路电流与通过R₂的电流之比为5:2。若将R₁、R₂串联在电路中，它们两端的电压之比U₁:U₂为","choices":["2:3","3:2","5:2","2:5"],"answer":0,"explain":"并联时I:I₂=5:2，则I₁:I₂=3:2。并联电压相等，电流与电阻成反比，R₁:R₂=2:3。串联时电流相等，电压与电阻成正比，U₁:U₂=R₁:R₂=2:3。容易把电流比直接当作电压比。"},
    {"id":"wl.dianlu-L4-05","module":"wl.dianlu","level":4,"kp":"特殊方法测电阻","prompt":"只用一只电压表和阻值已知的定值电阻R₀测未知电阻Rx：Rx与R₀串联接在电源电压不变的电源上，电压表并联在Rx两端，开关S₂并联在R₀两端。只闭合S₁时电压表示数为U₁；S₁、S₂都闭合时电压表示数为U₂。则Rx的表达式为","choices":["Rx=U₂R₀/U₁","Rx=U₁R₀/(U₂−U₁)","Rx=(U₂−U₁)R₀/U₁","Rx=U₁R₀/U₂"],"answer":1,"explain":"S₂闭合时R₀被短路，电压表示数U₂等于电源电压。只闭合S₁时两电阻串联，Rx两端电压U₁，R₀两端电压U₂−U₁，电流I=(U₂−U₁)/R₀，所以Rx=U₁/I=U₁R₀/(U₂−U₁)。选(U₂−U₁)R₀/U₁是把两电阻的电压弄反了。"},
    {"id":"wl.diangong-L1-01","module":"wl.diangong","level":1,"kp":"电能与电功","prompt":"家庭电路中电能表的计量单位是kW·h（度），1 kW·h等于","choices":["3.6×10^{3} J","1000 J","3.6×10^{6} J","3600 W"],"answer":2,"explain":"1 kW·h=1000 W×3600 s=3.6×10^{6} J。kW·h是电能（电功）的单位，W是功率的单位，不能把电能写成3600 W。"},
    {"id":"wl.diangong-L1-02","module":"wl.diangong","level":1,"kp":"安全用电","prompt":"下列做法中，符合安全用电原则的是","choices":["有金属外壳的用电器使用三孔插座","用湿手拔用电器的插头","发现有人触电，立即用手把他拉开","保险丝熔断后用铜丝代替"],"answer":0,"explain":"三孔插座能把金属外壳接地，外壳漏电时电流经地线导入大地，防止触电。湿手易导电；有人触电应先切断电源或用干燥木棍挑开电线；铜丝熔点高，电流过大时不能熔断，起不到保护作用。"},
    {"id":"wl.diangong-L1-03","module":"wl.diangong","level":1,"kp":"电流的磁效应","prompt":"首先发现通电导线周围存在磁场的科学家是","choices":["法拉第","焦耳","欧姆","奥斯特"],"answer":3,"explain":"1820年奥斯特发现了电流的磁效应。法拉第发现了电磁感应现象；焦耳研究了电流热效应（焦耳定律）；欧姆得出了电流与电压、电阻的关系（欧姆定律）。"},
    {"id":"wl.diangong-L1-04","module":"wl.diangong","level":1,"kp":"电动机与发电机","prompt":"发电机的工作原理是","choices":["电磁感应现象","通电导体在磁场中受到力的作用","电流的磁效应","电流的热效应"],"answer":0,"explain":"发电机利用闭合电路的一部分导体在磁场中做切割磁感线运动产生感应电流的原理，即电磁感应，把机械能转化为电能。“通电导体在磁场中受力”是电动机的原理；电磁铁利用电流的磁效应。"},
    {"id":"wl.diangong-L1-05","module":"wl.diangong","level":1,"kp":"能源与信息","prompt":"下列能源中，属于可再生能源的是","choices":["石油","天然气","煤","太阳能"],"answer":3,"explain":"太阳能、风能、水能等能在自然界源源不断地得到，是可再生能源。煤、石油、天然气是化石能源，短期内不能从自然界得到补充，属于不可再生能源。"},
    {"id":"wl.diangong-L2-01","module":"wl.diangong","level":2,"kp":"电功率计算","prompt":"一个标有“220 V　1100 W”的电热水壶，正常工作时的电流和电阻分别是","choices":["5 A，242 Ω","5 A，44 Ω","0.2 A，44 Ω","0.2 A，1100 Ω"],"answer":1,"explain":"正常工作时I=P/U=1100 W/220 V=5 A，R=U/I=220 V/5 A=44 Ω（或R=U²/P=48400/1100 Ω=44 Ω）。把U/P当作电流会得到0.2 A。"},
    {"id":"wl.diangong-L2-02","module":"wl.diangong","level":2,"kp":"额定功率与实际功率","prompt":"将一只标有“220 V　100 W”的灯泡接在110 V的电路中（不考虑灯丝电阻变化），灯泡的实际功率为","choices":["50 W","100 W","25 W","12.5 W"],"answer":2,"explain":"灯丝电阻R=U额²/P额=220²/100 Ω=484 Ω，P实=U实²/R=110²/484 W=25 W。电压变为原来的一半，功率变为原来的1/4，而不是一半。"},
    {"id":"wl.diangong-L2-03","module":"wl.diangong","level":2,"kp":"电能表计算","prompt":"某电能表上标有“3000 r/(kW·h)”。只让一个用电器工作，6 min内电能表转盘转了300转，该用电器的电功率为","choices":["100 W","3000 W","1000 W","600 W"],"answer":2,"explain":"消耗电能W=300/3000 kW·h=0.1 kW·h，t=6 min=0.1 h，P=W/t=0.1 kW·h/0.1 h=1 kW=1000 W。时间要换算成小时与kW·h对应。"},
    {"id":"wl.diangong-L2-04","module":"wl.diangong","level":2,"kp":"焦耳定律","prompt":"阻值为10 Ω的电阻丝，通过2 A的电流，1 min内产生的热量为","choices":["2400 J","1200 J","40 J","20 J"],"answer":0,"explain":"由焦耳定律Q=I²Rt=(2 A)²×10 Ω×60 s=2400 J。电流没有平方会得到1200 J；时间不换算成秒会得到40 J。"},
    {"id":"wl.diangong-L2-05","module":"wl.diangong","level":2,"kp":"磁场与磁感线","prompt":"关于磁场和磁感线，下列说法正确的是","choices":["磁感线是磁场中真实存在的曲线","磁感线是为了形象描述磁场而假想的曲线","磁体外部的磁感线从S极出发，回到N极","地磁的北极在地理北极附近"],"answer":1,"explain":"磁场真实存在，磁感线是为描述磁场而引入的假想曲线。磁体外部磁感线从N极出发回到S极；地磁北极在地理南极附近，地磁南极在地理北极附近，所以小磁针N极指北。"},
    {"id":"wl.diangong-L2-06","module":"wl.diangong","level":2,"kp":"家庭电路","prompt":"家庭电路中的空气开关“跳闸”，可能的原因是","choices":["电路中某盏灯的灯丝断了","电路中的开关接触不良","家庭电路的电压太低","电路中发生了短路或用电器总功率过大"],"answer":3,"explain":"空气开关在电流过大时自动断开。家庭电路电流过大的原因有两个：短路和用电器总功率过大。灯丝断、开关接触不良会使电流变小或为零，电压低也会使电流变小，都不会使空气开关跳闸。"},
    {"id":"wl.diangong-L3-01","module":"wl.diangong","level":3,"kp":"额定功率与实际功率","prompt":"将标有“6 V　3 W”的灯L₁和“6 V　6 W”的灯L₂串联接在6 V的电源上（不考虑灯丝电阻变化），则","choices":["L₂更亮","两灯一样亮","L₁更亮","两灯都能正常发光"],"answer":2,"explain":"R₁=U²/P=36/3 Ω=12 Ω，R₂=36/6 Ω=6 Ω。串联时电流相等，由P=I²R，电阻大的L₁实际功率大，更亮。两灯分压后都小于6 V，都不能正常发光。“额定功率大就更亮”只适用于并联在额定电压下。"},
    {"id":"wl.diangong-L3-02","module":"wl.diangong","level":3,"kp":"电磁铁","prompt":"在探究“影响电磁铁磁性强弱的因素”实验中，下列说法正确的是","choices":["线圈匝数越少，电磁铁的磁性越强","调节滑动变阻器使电流减小，吸引的大头针会增多","电磁铁磁性强弱与电流方向有关","通过电磁铁吸引大头针的数目来判断磁性强弱"],"answer":3,"explain":"磁性强弱不能直接看到，通过吸引大头针的数目来反映，属于转换法。电流越大、线圈匝数越多，电磁铁磁性越强；电流方向只改变磁极，不改变磁性强弱。"},
    {"id":"wl.diangong-L3-03","module":"wl.diangong","level":3,"kp":"电动机与发电机","prompt":"关于直流电动机，下列说法正确的是","choices":["只改变线圈中电流的方向，电动机的转动方向会改变","同时改变电流方向和磁场方向，电动机的转动方向会改变","电动机工作时将机械能转化为电能","电动机是利用电磁感应原理工作的"],"answer":0,"explain":"通电导体在磁场中受力的方向与电流方向和磁场方向都有关，只改变其中一个，转向改变；两个同时改变，转向不变。电动机将电能转化为机械能，原理是通电线圈在磁场中受力转动；电磁感应是发电机的原理。"},
    {"id":"wl.diangong-L3-04","module":"wl.diangong","level":3,"kp":"多档位电热器","prompt":"某电热水器有加热和保温两档，电路由R₁=44 Ω和R₂=176 Ω串联接在220 V电路中，开关S与R₂并联。S闭合时R₂被短路。加热功率和保温功率分别是","choices":["1100 W，275 W","1100 W，220 W","220 W，1100 W","880 W，220 W"],"answer":1,"explain":"S闭合，只有R₁工作，电阻小，功率大，为加热档：P=U²/R₁=48400/44 W=1100 W。S断开，R₁、R₂串联，总电阻220 Ω，为保温档：P=48400/220 W=220 W。用R₂单独计算得275 W是错误的。"},
    {"id":"wl.diangong-L3-05","module":"wl.diangong","level":3,"kp":"电磁感应","prompt":"蹄形磁体的两极上下放置，两极间的磁感线竖直向下。导体ab垂直于纸面水平放置在两极之间，并通过开关与灵敏电流计组成电路。下列操作中能使电流计指针偏转的是","choices":["闭合开关，使ab竖直向上运动","断开开关，使ab水平向左运动","闭合开关，使ab水平向左运动","闭合开关，使ab静止在磁场中"],"answer":2,"explain":"产生感应电流的条件：电路闭合，且一部分导体在磁场中做切割磁感线运动。磁感线竖直，ab竖直运动不切割磁感线；开关断开电路不闭合；导体静止不切割，这些都不能产生感应电流。"},
    {"id":"wl.diangong-L4-01","module":"wl.diangong","level":4,"kp":"额定功率与实际功率","prompt":"将标有“6 V　3 W”的灯L₁和“6 V　6 W”的灯L₂串联接在9 V的电源上（不考虑灯丝电阻变化），下列说法正确的是","choices":["L₂正常发光，L₁的实际功率为1.5 W","两灯都能正常发光","L₁会被烧坏，L₂不发光","L₁正常发光，L₂的实际功率为1.5 W"],"answer":3,"explain":"R₁=12 Ω，R₂=6 Ω，串联I=9 V/18 Ω=0.5 A。L₁额定电流I₁=3 W/6 V=0.5 A，恰好正常发光；L₂额定电流1 A，实际功率P₂=I²R₂=0.25×6 W=1.5 W。串联时分压U₁=6 V、U₂=3 V，也可验证。"},
    {"id":"wl.diangong-L4-02","module":"wl.diangong","level":4,"kp":"电功率图像与综合","stem":"某小灯泡的电流与其两端电压的关系如下表：\nU/V：1　　2　　3　　4　　6\nI/A：0.20　0.30　0.40　0.45　0.50","prompt":"将该灯泡与一个10 Ω的定值电阻串联接在某电源上，测得电路中电流为0.4 A。电源电压和灯泡的实际功率分别是","choices":["4 V，1.2 W","7 V，1.2 W","7 V，1.6 W","4 V，1.6 W"],"answer":1,"explain":"电流0.4 A时，由表知灯泡两端电压为3 V，P灯=UI=3 V×0.4 A=1.2 W。定值电阻两端电压U=IR=0.4×10 V=4 V，电源电压为3 V+4 V=7 V。灯丝电阻会变化，不能用某一组数据的电阻代替。1.6 W是电阻的功率。"},
    {"id":"wl.diangong-L4-03","module":"wl.diangong","level":4,"kp":"滑变功率极值","prompt":"电源电压6 V不变，定值电阻R₁=10 Ω与滑动变阻器R₂（最大阻值20 Ω）串联。移动滑片，滑动变阻器R₂消耗的最大功率为","choices":["0.9 W","3.6 W","1.8 W","0.8 W"],"answer":0,"explain":"P₂=I²R₂=U²R₂/(R₁+R₂)²。可以验证：R₂=5 Ω时P₂=0.8 W，R₂=10 Ω时P₂=36×10/400 W=0.9 W，R₂=20 Ω时P₂=0.8 W。当R₂=R₁=10 Ω时功率最大，为0.9 W。3.6 W是R₂=0时R₁的功率。"},
    {"id":"wl.diangong-L4-04","module":"wl.diangong","level":4,"kp":"家庭电路故障","prompt":"闭合开关后家中电灯不亮，用试电笔分别测试灯座两个接线柱，试电笔的氖管都发光。故障可能是","choices":["进户零线断路","进户火线断路","灯丝断了","灯泡短路"],"answer":0,"explain":"两个接线柱都使氖管发光，说明都与火线连通。若灯丝断了，与零线相连的一端不会发光；火线断路时氖管都不发光；灯泡短路会使保险装置断开。只有零线断路时，火线经灯丝使另一端也带电，氖管都发光。"},
    {"id":"wl.diangong-L4-05","module":"wl.diangong","level":4,"kp":"电热效率计算","prompt":"一个额定功率为1000 W的电热水壶正常工作7 min，将1 kg的水从20 ℃加热到100 ℃[c_{水}=4.2×10^{3} J/(kg·℃)]。电热水壶的加热效率为","choices":["75%","60%","80%","90%"],"answer":2,"explain":"Q吸=cmΔt=4.2×10^{3}×1×80 J=3.36×10^{5} J；W=Pt=1000 W×420 s=4.2×10^{5} J；η=Q吸/W=3.36×10^{5}/4.2×10^{5}=80%。时间要换算成420 s，Δt是80 ℃。"},
  ],
});
